def _agent_preview_error(code, message, status=400, **details):
    error = {"code": code, "message": message}
    if details:
        error["details"] = details
    return {"ok": False, "error": error, "_status": status}


def _agent_preview_sensitive_path(relative_path):
    parts = [part for part in str(relative_path or "").replace("\\", "/").split("/") if part]
    for part in parts:
        lowered = part.lower()
        if lowered.startswith(".") or lowered in _AGENT_PREVIEW_SECRET_BASENAMES:
            return True
        if lowered.startswith(("credentials.", "secrets.", "tokens.", "private-key.")):
            return True
        if lowered.endswith(_AGENT_PREVIEW_SECRET_SUFFIXES):
            return True
    return False


def _map_agent_preview_absolute_path(raw_path):
    requested = str(raw_path or "").strip()
    candidates = [requested]
    gateway_root = _openclaw_gateway_home_path()
    for host_root in [gateway_root, os.environ.get("VO_OPENCLAW_GATEWAY_PATH")]:
        if not host_root:
            continue
        mapped = map_host_path_to_container(requested, host_root=host_root, container_root=WORKSPACE_BASE)
        if mapped and mapped not in candidates:
            candidates.append(mapped)
    return candidates


def _agent_preview_workspace_root(agent_id, agent):
    raw = str((agent or {}).get("workspace") or (agent or {}).get("home") or "").strip()
    candidates = []
    if raw:
        if is_windows_absolute(raw):
            if os.name == "nt":
                candidates.append(os.path.abspath(os.path.expanduser(raw)))
            else:
                candidates.extend(_map_agent_preview_absolute_path(raw))
        else:
            candidates.append(os.path.abspath(os.path.expanduser(raw)))
            candidates.extend(_map_agent_preview_absolute_path(raw))
    fallback = _agent_workspace_abs_path(agent_id, agent)
    if fallback:
        candidates.append(fallback)
    for candidate in candidates:
        if candidate and os.path.isdir(candidate):
            return os.path.abspath(candidate)
    return ""


def _agent_pc_context(agent_id):
    """Return the canonical agent record and server-visible Home path."""
    agent = _find_agent_record(agent_id)
    if not agent:
        raise AgentPCError("agent_not_found", "Unknown agent id for Agent PC.", 404, agentId=agent_id)
    canonical_id = AGENT_PC_STORE.ensure_profile(agent)
    return canonical_id, agent, _agent_preview_workspace_root(canonical_id, agent)


_AGENT_PC_TOOL_PATH_KEYS = (
    "path", "file_path", "filePath", "file", "filename", "output_path", "outputPath",
    "output_file", "outputFile", "artifact_path", "artifactPath", "target_path", "targetPath",
)
_AGENT_PC_TOOL_URL_KEYS = ("url", "uri", "href", "target_url", "targetUrl")


def _agent_pc_tool_activity_payload(tool_name, arguments=None, *, phase="", result=None, source="provider", run_id="", session_id=""):
    """Normalize provider tool data into the durable Agent PC vocabulary."""
    args = arguments if isinstance(arguments, dict) else {}
    name = str(tool_name or "").replace("functions.", "").strip()
    lowered = name.lower()
    for key in _AGENT_PC_TOOL_URL_KEYS:
        value = args.get(key)
        if isinstance(value, str) and value.strip():
            parsed = urllib.parse.urlparse(value.strip())
            if parsed.scheme in {"http", "https"} and parsed.netloc:
                return {
                    "kind": "url", "url": value.strip(), "title": parsed.netloc,
                    "toolName": name, "source": source, "phase": phase,
                    "runId": run_id, "sessionId": session_id,
                }
    if re.search(r"(^|[._-])(browser|agent[_-]?browser|playwright|puppeteer)([._-]|$)", lowered):
        return {
            "kind": "browser", "title": "Live Agent Browser", "toolName": name,
            "source": source, "phase": phase, "runId": run_id, "sessionId": session_id,
        }
    path = ""
    for key in _AGENT_PC_TOOL_PATH_KEYS:
        value = args.get(key)
        if isinstance(value, str) and value.strip():
            path = value.strip()
            break
    if not path:
        patch_text = str(args.get("patch") or args.get("input") or args.get("value") or "")
        match = re.search(r"^\*\*\* (?:Add|Update) File:\s*(.+)$", patch_text, re.MULTILINE)
        if match:
            path = match.group(1).strip()
    if not path and str(phase).lower() in {"result", "done", "complete", "completed"}:
        match = re.search(
            r"(?:generated(?:\s+and\s+saved)?|saved|created|written|output)(?:\s+(?:to|at))?[:\s]+([^\n\r]+\.(?:html?|md|txt|json|ya?ml|toml|csv|js|mjs|cjs|ts|tsx|jsx|py|go|rs|java|css|svg|png|jpe?g|gif|webp|pdf|mp4|webm|mov|mp3|wav|ogg))\b",
            str(result or ""),
            re.I,
        )
        if match:
            path = match.group(1).strip().strip("'\"`")
    if not path:
        return None
    return {
        "kind": "file", "path": path,
        "workdir": next((str(args.get(key)).strip() for key in ("workdir", "work_dir", "cwd", "directory") if args.get(key)), ""),
        "title": os.path.basename(path.replace("\\", "/")), "toolName": name,
        "source": source, "phase": phase, "runId": run_id, "sessionId": session_id,
    }


def _record_agent_pc_activity(agent_id, payload):
    if not payload:
        return None
    try:
        canonical_id, _agent, home_path = _agent_pc_context(agent_id)
        return AGENT_PC_STORE.record_activity(canonical_id, payload, home_path=home_path)
    except AgentPCError as exc:
        # Tool activity outside connected roots is still indexed by record_activity;
        # unknown/deleted agents and invalid resources should not disrupt runtimes.
        if exc.code not in {"agent_not_found", "invalid_kind", "invalid_url", "path_required", "sensitive_path"}:
            print(f"[AGENT PC] Activity ignored for {agent_id}: {exc.code}: {exc.message}")
    except Exception as exc:
        print(f"[AGENT PC] Activity observer failed for {agent_id}: {exc}")
    return None


def _observe_provider_tool_activity(agent_id, event):
    if not isinstance(event, dict):
        return
    payload = _agent_pc_tool_activity_payload(
        event.get("toolName") or event.get("tool") or event.get("name") or "",
        event.get("arguments") or event.get("args") or {},
        phase=event.get("phase") or event.get("status") or "",
        result=event.get("result"),
        source=event.get("source") or event.get("provider") or "provider-observer",
        run_id=event.get("runId") or event.get("run_id") or "",
        session_id=event.get("sessionId") or event.get("sessionKey") or "",
    )
    _record_agent_pc_activity(agent_id, payload)


gateway_presence.set_activity_observer(_observe_provider_tool_activity)


def _resolve_agent_preview_file(agent_id, raw_path, workdir=""):
    agent = _find_agent_record(agent_id)
    if not agent:
        return None, None, _agent_preview_error("agent_not_found", "Unknown agent id for preview.", 404, agentId=agent_id)
    root = _agent_preview_workspace_root(agent_id, agent)
    if not root:
        return None, None, _agent_preview_error("workspace_not_found", "Agent workspace is not available for preview.", 404, agentId=agent_id)

    raw_path = str(raw_path or "").strip()
    raw_workdir = str(workdir or "").strip()
    if not raw_path or "\x00" in raw_path or "\x00" in raw_workdir:
        return None, None, _agent_preview_error("invalid_path", "A file path is required.")

    root_real = os.path.realpath(root)

    def inside_root(candidate):
        try:
            real = os.path.realpath(os.path.abspath(candidate))
            return os.path.commonpath([root_real, real]) == root_real
        except (OSError, ValueError):
            return False

    candidate_bases = [root]
    if raw_workdir:
        if os.path.isabs(raw_workdir) or is_windows_absolute(raw_workdir):
            candidate_bases = _map_agent_preview_absolute_path(raw_workdir)
        else:
            candidate_bases = [os.path.join(root, raw_workdir)]

    candidates = []
    if os.path.isabs(raw_path) or is_windows_absolute(raw_path):
        candidates.extend(_map_agent_preview_absolute_path(raw_path))
    else:
        candidates.extend(os.path.join(base, raw_path) for base in candidate_bases)
        if raw_workdir:
            candidates.append(os.path.join(root, raw_path))

    outside_workspace = False
    for candidate in candidates:
        if not inside_root(candidate):
            outside_workspace = True
            continue
        full = os.path.realpath(os.path.abspath(candidate))
        relative = os.path.relpath(full, root_real).replace(os.sep, "/")
        if relative == ".." or relative.startswith("../"):
            outside_workspace = True
            continue
        if _agent_preview_sensitive_path(relative):
            return None, None, _agent_preview_error("sensitive_path", "Hidden and secret files cannot be previewed.", 403)
        if not os.path.isfile(full):
            continue
        extension = os.path.splitext(full)[1].lower()
        kind_info = _AGENT_PREVIEW_EXTENSION_KINDS.get(extension)
        if not kind_info:
            return None, None, _agent_preview_error("unsupported_file", "This file type is not supported by Agent Preview.", 415, extension=extension)
        kind, mime_type, language = kind_info
        size = os.path.getsize(full)
        maximum = AGENT_PREVIEW_MEDIA_MAX_BYTES if kind in {"video", "audio"} else (
            AGENT_PREVIEW_DOCUMENT_MAX_BYTES if kind in {"image", "pdf"} else AGENT_PREVIEW_TEXT_MAX_BYTES
        )
        if size > maximum:
            return None, None, _agent_preview_error("file_too_large", "File exceeds the preview size limit.", 413, size=size, maxBytes=maximum)
        stat = os.stat(full)
        descriptor = {
            "schemaVersion": AGENT_PREVIEW_SCHEMA_VERSION,
            "agentId": str((agent or {}).get("statusKey") or (agent or {}).get("id") or agent_id),
            "name": os.path.basename(full),
            "path": relative,
            "kind": kind,
            "mimeType": mime_type,
            "language": language,
            "size": size,
            "maxBytes": maximum,
            "modifiedAt": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(),
            "version": hashlib.sha256(f"{stat.st_mtime_ns}:{size}".encode("utf-8")).hexdigest()[:20],
        }
        return full, descriptor, None

    if outside_workspace:
        return None, None, _agent_preview_error("workspace_escape", "Preview files must stay inside the agent workspace.", 403)
    return None, None, _agent_preview_error("file_not_found", "Preview file was not found in the agent workspace.", 404)


def get_agent_preview_descriptor(agent_id, raw_path, workdir=""):
    _full, descriptor, error = _resolve_agent_preview_file(agent_id, raw_path, workdir)
    if error:
        status = error.pop("_status", 400)
        return False, error, status
    return True, {"ok": True, "schemaVersion": AGENT_PREVIEW_SCHEMA_VERSION, "preview": descriptor}, 200


def publish_agent_preview(payload):
    global _agent_preview_serial
    if not isinstance(payload, dict):
        error = _agent_preview_error("invalid_payload", "Preview payload must be an object.")
        return False, {key: value for key, value in error.items() if key != "_status"}, 400
    agent_id = str(payload.get("agentId") or payload.get("agent") or "").strip()
    kind = str(payload.get("kind") or payload.get("type") or ("file" if payload.get("path") else "")).strip().lower()
    if not agent_id:
        error = _agent_preview_error("agent_required", "agentId is required.")
        return False, {key: value for key, value in error.items() if key != "_status"}, 400
    target = {
        "agentId": agent_id,
        "kind": kind,
        "title": str(payload.get("title") or payload.get("label") or "").strip(),
        "source": str(payload.get("source") or "office-api").strip(),
    }
    if kind == "file":
        raw_path = str(payload.get("path") or payload.get("file") or "").strip()
        workdir = str(payload.get("workdir") or payload.get("cwd") or "").strip()
        _full, descriptor, error = _resolve_agent_preview_file(agent_id, raw_path, workdir)
        if error:
            status = error.pop("_status", 400)
            return False, error, status
        target.update({"path": raw_path, "workdir": workdir, "title": target["title"] or descriptor["name"]})
    elif kind == "url":
        raw_url = str(payload.get("url") or payload.get("target") or "").strip()
        parsed = urllib.parse.urlparse(raw_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            error = _agent_preview_error("invalid_url", "Only HTTP and HTTPS preview URLs are allowed.")
            return False, {key: value for key, value in error.items() if key != "_status"}, 400
        target.update({"url": raw_url, "title": target["title"] or parsed.netloc})
    elif kind == "browser":
        target["title"] = target["title"] or "Live Agent Browser"
    else:
        error = _agent_preview_error("invalid_kind", "Preview kind must be file, url, or browser.")
        return False, {key: value for key, value in error.items() if key != "_status"}, 400

    now = time.time()
    with _agent_preview_lock:
        _agent_preview_records[:] = [item for item in _agent_preview_records if now - float(item.get("createdEpoch") or 0) <= AGENT_PREVIEW_RECORD_MAX_AGE_SEC]
        _agent_preview_serial += 1
        record = {
            "id": f"preview-{_agent_preview_serial}-{uuid.uuid4().hex[:8]}",
            "serial": _agent_preview_serial,
            "createdAt": datetime.now(timezone.utc).isoformat(),
            "createdEpoch": now,
            "target": target,
        }
        _agent_preview_records.append(record)
        del _agent_preview_records[:-AGENT_PREVIEW_RECORD_LIMIT]
    _record_agent_pc_activity(agent_id, {
        **target,
        "operation": str(payload.get("operation") or payload.get("category") or ""),
        "toolName": str(payload.get("toolName") or "explicit_preview"),
        "runId": str(payload.get("runId") or ""),
        "sessionId": str(payload.get("sessionId") or payload.get("sessionKey") or ""),
    })
    public_record = {key: value for key, value in record.items() if key != "createdEpoch"}
    return True, {"ok": True, "schemaVersion": AGENT_PREVIEW_SCHEMA_VERSION, "preview": public_record}, 201


def list_agent_previews(after=0):
    try:
        cursor = max(0, int(after or 0))
    except (TypeError, ValueError, OverflowError):
        cursor = 0
    now = time.time()
    with _agent_preview_lock:
        _agent_preview_records[:] = [item for item in _agent_preview_records if now - float(item.get("createdEpoch") or 0) <= AGENT_PREVIEW_RECORD_MAX_AGE_SEC]
        rows = [{key: value for key, value in item.items() if key != "createdEpoch"} for item in _agent_preview_records if int(item.get("serial") or 0) > cursor]
        latest = _agent_preview_serial
    return {"ok": True, "schemaVersion": AGENT_PREVIEW_SCHEMA_VERSION, "cursor": latest, "previews": rows}


def _agent_pc_api_error(exc):
    if isinstance(exc, AgentPCError):
        return exc.payload(), exc.status
    traceback.print_exc()
    return {"ok": False, "error": {"code": "agent_pc_error", "message": str(exc)}}, 500


def _agent_pc_route_parts(request_path):
    prefix = "/api/agent-pc/"
    if not request_path.startswith(prefix):
        return []
    return [urllib.parse.unquote(part) for part in request_path[len(prefix):].split("/") if part]


def _agent_pc_summary(agent_id):
    try:
        canonical_id, _agent, home_path = _agent_pc_context(agent_id)
        return AGENT_PC_STORE.summary(canonical_id, home_path=home_path), 200
    except Exception as exc:
        return _agent_pc_api_error(exc)


def _agent_pc_tree(agent_id, query):
    try:
        params = urllib.parse.parse_qs(query)
        root_id = (params.get("rootId") or ["home"])[0]
        relative = (params.get("path") or [""])[0]
        canonical_id, _agent, home_path = _agent_pc_context(agent_id)
        result = AGENT_PC_STORE.list_tree(canonical_id, root_id, relative, home_path=home_path)
        return result, 200
    except Exception as exc:
        return _agent_pc_api_error(exc)


def _agent_pc_descriptor(agent_id, query):
    try:
        params = urllib.parse.parse_qs(query)
        root_id = (params.get("rootId") or ["home"])[0]
        relative = (params.get("path") or [""])[0]
        saved_id = (params.get("savedId") or [""])[0]
        canonical_id, _agent, home_path = _agent_pc_context(agent_id)
        if saved_id:
            _full, descriptor = AGENT_PC_STORE.resolve_saved(canonical_id, saved_id)
        else:
            _full, descriptor = AGENT_PC_STORE.resolve_file(canonical_id, root_id, relative, home_path=home_path)
        return {"ok": True, "schemaVersion": descriptor.get("schemaVersion"), "preview": descriptor}, 200
    except Exception as exc:
        return _agent_pc_api_error(exc)


def _agent_pc_mutation(agent_id, action, payload):
    try:
        canonical_id, _agent, home_path = _agent_pc_context(agent_id)
        if action == "activity":
            result = AGENT_PC_STORE.record_activity(canonical_id, payload, home_path=home_path)
        elif action == "roots":
            result = AGENT_PC_STORE.connect_root(canonical_id, payload)
        elif action == "saved":
            result = AGENT_PC_STORE.save_item(canonical_id, payload, home_path=home_path)
        elif action == "state":
            result = AGENT_PC_STORE.set_ui_state(canonical_id, payload.get("state") if isinstance(payload.get("state"), dict) else payload)
        else:
            raise AgentPCError("route_not_found", "Agent PC action was not found.", 404)
        return result, 200 if action == "state" else 201
    except Exception as exc:
        return _agent_pc_api_error(exc)


def _agent_pc_delete(agent_id, collection, item_id):
    try:
        canonical_id, _agent, _home_path = _agent_pc_context(agent_id)
        if collection == "roots":
            result = AGENT_PC_STORE.disconnect_root(canonical_id, item_id)
        elif collection == "saved":
            result = AGENT_PC_STORE.delete_saved(canonical_id, item_id)
        else:
            raise AgentPCError("route_not_found", "Agent PC action was not found.", 404)
        return result, 200
    except Exception as exc:
        return _agent_pc_api_error(exc)


def _resource_glob_matches(relpath, pattern):
    """Match a provider resource glob without letting ``*`` cross folders."""
    rel = str(relpath or "").replace("\\", "/").strip("/")
    raw = str(pattern or "").replace("\\", "/").strip("/")
    if not rel or not raw:
        return False
    chunks = []
    index = 0
    while index < len(raw):
        char = raw[index]
        if char == "*":
            if index + 1 < len(raw) and raw[index + 1] == "*":
                index += 2
                if index < len(raw) and raw[index] == "/":
                    chunks.append("(?:.*/)?")
                    index += 1
                else:
                    chunks.append(".*")
                continue
            chunks.append("[^/]*")
        elif char == "?":
            chunks.append("[^/]")
        else:
            chunks.append(re.escape(char))
        index += 1
    return re.fullmatch("".join(chunks), rel) is not None


def _agent_resource_schema(agent):
    provider_kind = str((agent or {}).get("providerKind") or "openclaw")
    manifest = _get_provider_registry().manifest(provider_kind)
    return manifest.resource_schema if manifest else []


def _resource_descriptor(agent, relpath, include_hidden=False):
    rel = _safe_workspace_relpath(relpath)
    if not rel:
        return None
    for raw in _agent_resource_schema(agent):
        if not isinstance(raw, dict):
            continue
        matching_patterns = [pattern for pattern in raw.get("paths") or [] if _resource_glob_matches(rel, pattern)]
        if not matching_patterns:
            continue
        hidden_parts = [part for part in rel.split("/") if part.startswith(".")]
        if hidden_parts:
            explicitly_declared = any(
                all(part in str(pattern).replace("\\", "/").split("/") for part in hidden_parts)
                for pattern in matching_patterns
            )
            if not explicitly_declared:
                return None
        item = dict(raw)
        item.setdefault("id", "resource")
        item.setdefault("label", "Native resource")
        item.setdefault("runtimeActive", False)
        item.setdefault("readable", True)
        item.setdefault("writable", False)
        item.setdefault("deletable", False)
        item.setdefault("creatable", bool(item.get("writable")))
        capabilities = agent.get("capabilities") if isinstance((agent or {}).get("capabilities"), dict) else {}
        if "resourcesRead" in capabilities:
            item["readable"] = bool(item.get("readable") and capabilities.get("resourcesRead"))
        if "resourcesWrite" in capabilities:
            writable = bool(item.get("writable") and capabilities.get("resourcesWrite"))
            item["writable"] = writable
            item["creatable"] = bool(item.get("creatable") and writable)
            item["deletable"] = bool(item.get("deletable") and writable)
        item["path"] = rel
        if not include_hidden and not item.get("readable"):
            return None
        return item
    return None


def _resolve_workspace_file(agent_key, agent, raw_path, allow_new=False, operation="read"):
    root = _agent_workspace_abs_path(agent_key, agent)
    if not root:
        return None, "", "Workspace files are not available for this platform", None
    rel = _safe_workspace_relpath(raw_path)
    if not rel:
        return None, "", "File path required", None
    resource = _resource_descriptor(agent, rel, include_hidden=True)
    if resource is None:
        return None, rel, "This path is not exposed by the provider resource contract", None
    if not resource.get("readable"):
        managed = str(resource.get("managedBy") or "provider settings")
        return None, rel, f"This sensitive native file is hidden; manage it through {managed}", resource
    requested_operation = str(operation or "read")
    if requested_operation in ("write", "create", "delete") and not resource.get("writable"):
        managed = str(resource.get("managedBy") or "the provider's native settings")
        return None, rel, f"This native resource is read-only; manage it through {managed}", resource
    if requested_operation == "create" and not resource.get("creatable"):
        return None, rel, "This provider does not allow creating files in that resource group", resource
    if requested_operation == "delete" and not resource.get("deletable"):
        return None, rel, "This provider does not allow deleting that native resource", resource
    ext = os.path.splitext(rel)[1].lower()
    if ext not in _WORKSPACE_TEXT_EXTS:
        return None, rel, "Only declared text resources can be opened", resource
    full = os.path.abspath(os.path.join(root, rel))
    if full != root and not full.startswith(root + os.sep):
        return None, rel, "File must stay inside the agent workspace", resource
    real_root = os.path.realpath(root)
    real_target = os.path.realpath(full if os.path.exists(full) else os.path.dirname(full))
    if real_target != real_root and not real_target.startswith(real_root + os.sep):
        return None, rel, "Symbolic-link paths outside the agent workspace are not allowed", resource
    if not allow_new and not os.path.isfile(full):
        return None, rel, "File not found", resource
    return full, rel, "", resource


def _read_workspace_text_file(agent_key, agent, relpath):
    full, rel, err, resource = _resolve_workspace_file(agent_key, agent, relpath)
    if err:
        return {"error": err, "_status": 400}
    size = os.path.getsize(full)
    if size > _WORKSPACE_FILE_LIMIT:
        return {"error": "File is too large for dashboard editing", "_status": 413}
    with open(full, "r", encoding="utf-8", errors="replace") as f:
        content = f.read()
    revision = hashlib.sha256(content.encode("utf-8")).hexdigest()
    return {
        "ok": True,
        "file": {
            "name": os.path.basename(rel),
            "path": rel,
            "kind": resource.get("id") if resource else "resource",
            "resourceLabel": resource.get("label") if resource else "Native resource",
            "runtimeActive": bool((resource or {}).get("runtimeActive")),
            "writable": bool((resource or {}).get("writable")),
            "deletable": bool((resource or {}).get("deletable")),
            "generated": bool((resource or {}).get("generated")),
            "managedBy": str((resource or {}).get("managedBy") or ""),
            "size": size,
            "modified": datetime.fromtimestamp(os.path.getmtime(full), timezone.utc).isoformat(),
            "content": content,
            "revision": revision,
        },
    }


def _resource_backup_root(agent_key):
    return os.path.join(STATUS_DIR, "resource-backups", _safe_agent_workspace_key(agent_key))


def _save_workspace_text_file(agent_key, agent, relpath, content, create=False, expected_revision=""):
    root = _agent_workspace_abs_path(agent_key, agent)
    safe_rel = _safe_workspace_relpath(relpath)
    target_exists = bool(root and safe_rel and os.path.exists(os.path.join(root, safe_rel)))
    requested_operation = "create" if create and not target_exists else "write"
    full, rel, err, _resource = _resolve_workspace_file(
        agent_key, agent, relpath, allow_new=create, operation=requested_operation
    )
    if err:
        return {"error": err, "_status": 400}
    text = str(content or "")
    if len(text.encode("utf-8")) > _WORKSPACE_FILE_LIMIT:
        return {"error": "File content is too large", "_status": 413}
    old_text = ""
    old_revision = ""
    backup_id = ""
    if os.path.isfile(full):
        with open(full, "r", encoding="utf-8", errors="replace") as handle:
            old_text = handle.read()
        old_revision = hashlib.sha256(old_text.encode("utf-8")).hexdigest()
        if expected_revision and str(expected_revision) != old_revision:
            return {
                "error": "This file changed after it was opened. Reload it before saving.",
                "code": "revision_conflict",
                "currentRevision": old_revision,
                "_status": 409,
            }
        backup_id = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ")
        backup_path = os.path.join(_resource_backup_root(agent_key), backup_id, rel)
        data_owner.makedirs(os.path.dirname(backup_path), exist_ok=True)
        shutil.copy2(full, backup_path)
        data_owner.adopt(backup_path)
    data_owner.makedirs(os.path.dirname(full), exist_ok=True)
    _atomic_write_text(full, text)
    revision = hashlib.sha256(text.encode("utf-8")).hexdigest()
    return {
        "ok": True,
        "saved": rel,
        "revision": revision,
        "previousRevision": old_revision,
        "backupId": backup_id,
    }


def _preview_workspace_text_file(agent_key, agent, relpath, content, create=False):
    root = _agent_workspace_abs_path(agent_key, agent)
    safe_rel = _safe_workspace_relpath(relpath)
    target_exists = bool(root and safe_rel and os.path.exists(os.path.join(root, safe_rel)))
    requested_operation = "create" if create and not target_exists else "write"
    full, rel, err, _resource = _resolve_workspace_file(
        agent_key, agent, relpath, allow_new=create, operation=requested_operation
    )
    if err:
        return {"error": err, "_status": 400}
    old_text = ""
    if os.path.isfile(full):
        with open(full, "r", encoding="utf-8", errors="replace") as handle:
            old_text = handle.read()
    new_text = str(content or "")
    return {
        "ok": True,
        "path": rel,
        "revision": hashlib.sha256(old_text.encode("utf-8")).hexdigest() if os.path.isfile(full) else "",
        "changed": old_text != new_text,
        "diff": "".join(difflib.unified_diff(
            old_text.splitlines(keepends=True),
            new_text.splitlines(keepends=True),
            fromfile=f"{rel} (current)",
            tofile=f"{rel} (proposed)",
        ))[:100000],
    }


def _list_workspace_file_revisions(agent_key, agent, relpath):
    rel = _safe_workspace_relpath(relpath)
    if not rel:
        return {"error": "File path required", "_status": 400}
    _full, _rel, err, _resource = _resolve_workspace_file(agent_key, agent, rel, allow_new=True)
    if err:
        return {"error": err, "_status": 400}
    root = _resource_backup_root(agent_key)
    items = []
    if os.path.isdir(root):
        for backup_id in sorted(os.listdir(root), reverse=True):
            path = os.path.join(root, backup_id, rel)
            if not os.path.isfile(path):
                continue
            with open(path, "rb") as backup_file:
                revision = hashlib.sha256(backup_file.read()).hexdigest()
            items.append({
                "backupId": backup_id,
                "path": rel,
                "size": os.path.getsize(path),
                "modified": datetime.fromtimestamp(os.path.getmtime(path), timezone.utc).isoformat(),
                "revision": revision,
            })
    return {"ok": True, "path": rel, "revisions": items[:50]}


def _restore_workspace_file_revision(agent_key, agent, relpath, backup_id):
    rel = _safe_workspace_relpath(relpath)
    safe_backup = re.sub(r"[^A-Za-z0-9_.-]+", "", str(backup_id or ""))
    backup = os.path.join(_resource_backup_root(agent_key), safe_backup, rel)
    if not rel or not safe_backup or not os.path.isfile(backup):
        return {"error": "Backup revision not found", "_status": 404}
    with open(backup, "r", encoding="utf-8", errors="replace") as handle:
        content = handle.read()
    return _save_workspace_text_file(agent_key, agent, rel, content, create=True)


def _delete_workspace_text_file(agent_key, agent, relpath):
    full, rel, err, _resource = _resolve_workspace_file(agent_key, agent, relpath, operation="delete")
    if err:
        return {"error": err, "_status": 400}
    backup_id = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S.%fZ")
    backup_path = os.path.join(_resource_backup_root(agent_key), backup_id, rel)
    data_owner.makedirs(os.path.dirname(backup_path), exist_ok=True)
    shutil.copy2(full, backup_path)
    data_owner.adopt(backup_path)
    os.remove(full)
    return {"ok": True, "deleted": rel, "backupId": backup_id}


def _workspace_file_summaries(agent_key, agent):
    ws_path = _agent_workspace_abs_path(agent_key, agent)
    if not ws_path:
        return []
    files = []
    skip_dirs = {".git", "__pycache__", "node_modules", ".venv", "venv"}
    preferred = {"AGENTS.md": -90, "IDENTITY.md": -89, "SOUL.md": -88, "USER.md": -87, "HEARTBEAT.md": -86, "MEMORY.md": -85, "TOOLS.md": -84}
    for root, dirs, names in os.walk(ws_path):
        dirs[:] = [d for d in dirs if d not in skip_dirs and not d.startswith(".cache")]
        depth = os.path.relpath(root, ws_path).count(os.sep)
        if depth > 3:
            dirs[:] = []
        for fname in names:
            ext = os.path.splitext(fname)[1].lower()
            if ext not in _WORKSPACE_TEXT_EXTS:
                continue
            fpath = os.path.join(root, fname)
            try:
                size = os.path.getsize(fpath)
                rel = os.path.relpath(fpath, ws_path).replace(os.sep, "/")
                resource = _resource_descriptor(agent, rel)
                if not resource:
                    continue
                real_ws = os.path.realpath(ws_path)
                real_file = os.path.realpath(fpath)
                if real_file != real_ws and not real_file.startswith(real_ws + os.sep):
                    continue
                if size > _WORKSPACE_FILE_LIMIT:
                    kind = "large-text"
                elif rel.startswith("memory/"):
                    kind = "daily-note"
                elif rel.startswith("notes/"):
                    kind = "note-file"
                else:
                    kind = "workspace"
                files.append({
                    "name": fname,
                    "path": rel,
                    "kind": kind,
                    "resourceId": resource.get("id", "resource"),
                    "resourceLabel": resource.get("label", "Native resource"),
                    "runtimeActive": bool(resource.get("runtimeActive")),
                    "writable": bool(resource.get("writable")),
                    "creatable": bool(resource.get("creatable")),
                    "deletable": bool(resource.get("deletable")),
                    "generated": bool(resource.get("generated")),
                    "managedBy": str(resource.get("managedBy") or ""),
                    "size": size,
                    "modified": datetime.fromtimestamp(os.path.getmtime(fpath), timezone.utc).isoformat(),
                    "_rank": preferred.get(rel, 0),
                })
            except OSError:
                pass
    files.sort(key=lambda f: (f.pop("_rank", 0), f.get("path", "")))
    return files[:120]


def _agent_skill_summaries(agent_key, agent):
    capabilities = agent.get("capabilities") if isinstance(agent.get("capabilities"), dict) else {}
    if not capabilities.get("skills"):
        return []
    result = _handle_skill_list(agent_key)
    keep = {
        "name", "displayName", "type", "description", "content", "rootId",
        "rootLabel", "scope", "runtimeActive", "writable", "relativePath",
        "valid", "validationError",
    }
    return [
        {key: value for key, value in s.items() if key in keep}
        for s in result.get("skills", [])[:40]
    ]


def _agent_project_tasks(agent):
    aliases = {
        str(agent.get("id") or ""),
        str(agent.get("statusKey") or ""),
        str(agent.get("providerAgentId") or ""),
    }
    aliases.discard("")
    data = _load_projects()
    items = []
    for project in data.get("projects", []):
        columns = {c.get("id"): c.get("title", "") for c in project.get("columns", [])}
        for task in project.get("tasks", []):
            if str(task.get("assignee") or "") not in aliases:
                continue
            items.append({
                "projectId": project.get("id", ""),
                "projectTitle": project.get("title", ""),
                "taskId": task.get("id", ""),
                "title": task.get("title", ""),
                "priority": task.get("priority", "medium"),
                "column": columns.get(task.get("columnId"), ""),
                "completed": bool(task.get("completedAt")),
                "updatedAt": task.get("updatedAt") or project.get("updatedAt", ""),
            })
    items.sort(key=lambda x: x.get("updatedAt") or "", reverse=True)
    return items[:25]


def _agent_recent_activity(agent_key, agent):
    if agent.get("providerKind") == "hermes":
        profile = agent.get("profile") or agent.get("providerAgentId") or "default"
        messages = _load_hermes_history(profile)[-80:]
    elif agent.get("providerKind") == "codex":
        profile = agent.get("profile") or agent.get("providerAgentId") or "default"
        messages = _load_codex_history(profile)[-80:]
    elif agent.get("providerKind") == "claude-code":
        profile = agent.get("profile") or agent.get("providerAgentId") or "main"
        messages = _load_claude_code_history(profile)[-80:]
    elif agent.get("providerKind", "openclaw") != "openclaw":
        profile = agent.get("profile") or agent.get("providerAgentId") or "main"
        messages = _load_provider_history(agent.get("providerKind"), profile)[-80:]
    else:
        messages = get_agent_messages(agent_key, max_messages=80)
    return messages[-80:] if isinstance(messages, list) else []


def _agent_score_info(agent_key):
    try:
        data = _load_scores()
        return data.get("agents", {}).get(agent_key, {"score": 0, "completed": 0, "streak": 0, "history": []})
    except Exception:
        return {"score": 0, "completed": 0, "streak": 0, "history": []}


def _office_config_agent_override(agent_key):
    path = os.path.join(STATUS_DIR, "office-config.json")
    try:
        with open(path, "r") as f:
            cfg = json.load(f)
    except Exception:
        return {}
    for item in cfg.get("agents", []) or []:
        if agent_key in (item.get("id"), item.get("statusKey")):
            return item
    return {}


OFFICE_CONFIG_FILE_NAME = "office-config.json"
# Last browser save per layout file: {"rev", "client", "seq"} (v0.10.1 saves).
_OFFICE_SAVE_LAST = {}


def _office_config_rev_of(raw):
    """Revision of the saved layout = hash of its bytes ("0" = nothing saved yet).
    Any writer (browser, agent API, server-side agent patch) changes it."""
    return hashlib.sha1(raw).hexdigest()[:16] if raw else "0"


def _office_config_read_with_rev(path):
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return None, "0"
    return raw, _office_config_rev_of(raw)


def _office_save_check(path, base_rev, client, seq):
    """Decide a layout POST under the file lock: None = write it, else the 409 body.

    A save names the revision it was based on (X-VO-Base-Rev / If-Match). It is
    refused when the layout changed since, unless the change is this tab's own
    older save (its newer snapshot passes it). A tab's older snapshot arriving
    after its newer one is refused. No base revision = last write wins (old API)."""
    raw, current = _office_config_read_with_rev(path)
    last = _OFFICE_SAVE_LAST.get(os.path.abspath(path)) or {}
    own_last = bool(client) and last.get("client") == client and last.get("rev") == current
    if own_last and seq is not None and last.get("seq") is not None and seq <= last["seq"]:
        return {"ok": False, "error": "stale_save", "rev": current,
                "message": "A newer save from this window is already stored."}
    # The response layer's ETag (24 hex of the same sha1, maybe -gz) also names this revision.
    if base_rev is None or base_rev == current or (
            raw and len(base_rev) >= 16 and hashlib.sha1(raw).hexdigest().startswith(base_rev)):
        return None
    if own_last and seq is not None and (last.get("seq") is None or seq > last["seq"]):
        return None
    try:
        config = json.loads(raw.decode("utf-8")) if raw else None
    except ValueError:
        config = None
    return {"ok": False, "error": "conflict", "rev": current, "config": config,
            "message": "The office layout was changed somewhere else since this window loaded it."}


def _office_save_write(path, body, client, seq):
    """Store a browser/API layout (caller holds the file lock); returns the new revision."""
    try:
        _read_json_state(path, default=None)
    except JsonStateError:
        # Keep the unreadable file for recovery instead of overwriting it.
        try:
            os.replace(path, f"{path}.unreadable-{int(time.time())}")
        except OSError:
            pass
    _write_json_atomic(path, body, indent=None)
    rev = _office_config_read_with_rev(path)[1]
    _OFFICE_SAVE_LAST[os.path.abspath(path)] = {"rev": rev, "client": client, "seq": seq}
    return rev


def _office_save_headers(headers):
    base = headers.get("X-VO-Base-Rev") or headers.get("If-Match")
    base = str(base or "").strip()
    if base.startswith("W/"):
        base = base[2:]
    base = base.strip().strip('"').strip()
    if base.endswith("-gz"):
        base = base[:-3]
    base = base or None
    client = str(headers.get("X-VO-Client") or "").strip()[:80] or None
    try:
        seq = int(str(headers.get("X-VO-Save-Seq") or "").strip())
    except ValueError:
        seq = None
    return base, client, seq


def _default_office_config():
    """The bundled default layout with the live roster (what GET serves when nothing is saved)."""
    default_path = os.path.join(os.path.dirname(__file__) or ".", "default-office-config.json")
    with open(default_path, "r", encoding="utf-8") as handle:
        return json.loads(_patch_default_config_agents(handle.read()))


def _update_office_config_agent(agent_key, patch):
    path = os.path.join(STATUS_DIR, OFFICE_CONFIG_FILE_NAME)
    with _json_file_lock(path):
        try:
            cfg = _read_json_state(path, default=None)
        except JsonStateError as exc:
            # Never rebuild the layout from scratch after a failed read (BE-18).
            print(f"office-config.json not updated: {exc}")
            return None
        if cfg is None:
            try:
                cfg = _default_office_config()
            except (OSError, ValueError):
                return None
        item = _apply_office_config_agent_patch(cfg, agent_key, patch)
        _write_json_atomic(path, cfg)
        return item


def _apply_office_config_agent_patch(cfg, agent_key, patch):
    agents = cfg.setdefault("agents", [])
    item = None
    for candidate in agents:
        if agent_key in (candidate.get("id"), candidate.get("statusKey")):
            item = candidate
            break
    if item is None:
        item = {"id": agent_key, "statusKey": agent_key}
        agents.append(item)
    for key, value in patch.items():
        if value is not None:
            item[key] = value
    return item


def _get_agent_workspace_payload(agent_key):
    refresh_agent_maps()
    agent = _find_agent_record(agent_key)
    if not agent:
        return {"error": f"Unknown agent: {agent_key}", "_status": 404}

    key = agent.get("statusKey") or agent.get("id") or agent_key
    store_key = _safe_agent_workspace_key(key)
    store = _load_agent_workspaces()
    workspace = store.setdefault(store_key, {})
    workspace.setdefault("bulletin", [])
    workspace.setdefault("tasks", [])
    workspace.setdefault("notes", [])
    workspace.setdefault("settings", {})
    workspace.setdefault("updatedAt", "")

    presence = _get_normalized_presence_state().get(key, {"state": "idle", "task": "", "updated": 0})
    override = _office_config_agent_override(key)
    payload_agent = {
        "id": agent.get("id", key),
        "statusKey": key,
        "providerKind": agent.get("providerKind", "openclaw"),
        "providerType": agent.get("providerType", "runtime"),
        "providerAgentId": agent.get("providerAgentId", agent.get("id", key)),
        "profile": agent.get("profile", ""),
        "name": override.get("name") or agent.get("name", key),
        "displayName": override.get("displayName") or override.get("name") or agent.get("name", key),
        "emoji": override.get("emoji") or agent.get("emoji", "🤖"),
        "role": override.get("role") or agent.get("role", ""),
        "branch": override.get("branch") or agent.get("branch", ""),
        "color": override.get("color", ""),
        "model": agent.get("model", ""),
        "provider": agent.get("provider", ""),
        "lastActiveAt": agent.get("lastActiveAt", 0),
        "available": bool(agent.get("available", True)),
        "connectionState": str(agent.get("connectionState") or "connected"),
        "capabilities": agent.get("capabilities") if isinstance(agent.get("capabilities"), dict) else {},
        "providerConnectionId": agent.get("providerConnectionId", "default"),
        "workspace": agent.get("workspace") or agent.get("home") or "",
    }
    heartbeat = ""
    heartbeat_revision = ""
    provider_kind = agent.get("providerKind", "openclaw")
    capabilities = payload_agent["capabilities"]
    manifest = _get_provider_registry().manifest(provider_kind)
    resource_schema = manifest.resource_schema if manifest else []
    skill_schema = manifest.skill_schema if manifest else []
    any_writable_resource = any(
        isinstance(resource, dict)
        and resource.get("readable", True)
        and resource.get("writable", False)
        for resource in resource_schema
    )
    heartbeat_applicable = any(
        "HEARTBEAT.md" in (resource.get("paths") or [])
        for resource in resource_schema
        if isinstance(resource, dict)
    )
    if heartbeat_applicable:
        hb = _resolve_workspace_file(key, agent, "HEARTBEAT.md", allow_new=True)[0]
        if hb and os.path.isfile(hb):
            try:
                with open(hb, "r", encoding="utf-8", errors="replace") as f:
                    heartbeat = f.read()
                heartbeat_revision = hashlib.sha256(heartbeat.encode("utf-8")).hexdigest()
            except OSError:
                heartbeat = ""
    return {
        "ok": True,
        "agent": payload_agent,
        "presence": presence,
        "workspace": workspace,
        "files": _workspace_file_summaries(key, agent) if capabilities.get("resourcesRead") else [],
        "skills": _agent_skill_summaries(key, agent),
        "skillLibrary": _handle_skills_library_list().get("skills", []),
        "projectTasks": _agent_project_tasks(agent),
        "activity": _agent_recent_activity(key, agent),
        "score": _agent_score_info(key),
        "settings": {
            "heartbeatContent": heartbeat,
            # Send back as heartbeatRevision: a save over a newer HEARTBEAT.md is refused (409).
            "heartbeatRevision": heartbeat_revision,
            "heartbeatApplicable": heartbeat_applicable,
            "cronApplicable": provider_kind == "openclaw",
            "filesApplicable": bool(capabilities.get("resourcesRead")),
            "filesWritable": bool(capabilities.get("resourcesWrite") and any_writable_resource),
            "profileEditable": bool(capabilities.get("profileEdit")),
            "agentSkillsApplicable": bool(capabilities.get("skills")),
            "skillLibraryApplicable": True,
            # (a layer agent's model: per chat in its chat window, its default in Agent Providers)
            "modelEditable": bool(capabilities.get("models") and provider_kind != "hermes"
                                  and not (_pl_owns() and provider_layer_turns.layer_agent(agent.get("id")))),
            "resourceSchema": resource_schema,
            "skillSchema": skill_schema,
        },
    }


def _handle_agent_workspace_update(agent_key, body):
    # One writer at a time for the whole multi-agent store (v0.10.1 saves): two
    # saves at once (any two agents) used to drop one of them.
    with _json_file_lock(AGENT_WORKSPACES_FILE):
        return _handle_agent_workspace_update_locked(agent_key, body)


def _handle_agent_workspace_update_locked(agent_key, body):
    payload = _get_agent_workspace_payload(agent_key)
    if not payload.get("ok"):
        return payload
    key = payload["agent"]["statusKey"]
    store_key = _safe_agent_workspace_key(key)
    try:
        store = _read_json_state(AGENT_WORKSPACES_FILE, default={})
    except JsonStateError as exc:
        # Never rebuild every agent's desk from nothing after a failed read.
        return {"error": f"The agent desk data cannot be read, so nothing was saved ({exc}).", "_status": 503}
    workspace = store.setdefault(store_key, {"bulletin": [], "tasks": [], "notes": [], "settings": {}})
    workspace.setdefault("bulletin", [])
    workspace.setdefault("tasks", [])
    workspace.setdefault("notes", [])
    workspace.setdefault("settings", {})
    action = (body.get("action") or "").strip()
    now = datetime.now(timezone.utc).isoformat()
    actor = (body.get("actor") or "user").strip()[:80] or "user"
    agent = payload["agent"]
    capabilities = agent.get("capabilities") if isinstance(agent.get("capabilities"), dict) else {}

    if action == "addBulletin":
        text = (body.get("text") or "").strip()
        if not text:
            return {"error": "Bulletin text required", "_status": 400}
        workspace.setdefault("bulletin", []).insert(0, {
            "id": str(uuid.uuid4()),
            "text": text[:5000],
            "createdAt": now,
            "createdBy": actor,
            "pinned": bool(body.get("pinned", False)),
        })
        workspace["bulletin"] = workspace["bulletin"][:100]
    elif action == "deleteBulletin":
        item_id = str(body.get("id") or "")
        workspace["bulletin"] = [x for x in workspace.get("bulletin", []) if x.get("id") != item_id]
    elif action == "updateBulletin":
        item_id = str(body.get("id") or "")
        text = (body.get("text") or "").strip()
        for note in workspace.get("bulletin", []):
            if note.get("id") == item_id:
                note["text"] = text[:5000]
                note["updatedAt"] = now
                note["pinned"] = bool(body.get("pinned", note.get("pinned", False)))
                break
    elif action == "addTask":
        text = (body.get("text") or "").strip()
        if not text:
            return {"error": "Task text required", "_status": 400}
        workspace.setdefault("tasks", []).append({
            "id": str(uuid.uuid4()),
            "text": text[:1000],
            "detail": (body.get("detail") or "").strip()[:5000],
            "done": False,
            "status": "queued",
            "priority": (body.get("priority") or "normal").strip()[:40],
            "createdAt": now,
            "createdBy": actor,
            "due": (body.get("due") or "").strip()[:80],
        })
        workspace["tasks"] = workspace["tasks"][:100]
        if not workspace.get("activeTaskId") and workspace.get("settings", {}).get("taskMode") == "single":
            workspace["activeTaskId"] = workspace["tasks"][-1]["id"]
            workspace["tasks"][-1]["status"] = "active"
    elif action == "updateTask":
        item_id = str(body.get("id") or "")
        for task in workspace.get("tasks", []):
            if task.get("id") == item_id:
                task["text"] = (body.get("text") or task.get("text") or "").strip()[:1000]
                task["detail"] = (body.get("detail") or task.get("detail") or "").strip()[:5000]
                task["due"] = (body.get("due") or "").strip()[:80]
                task["priority"] = (body.get("priority") or task.get("priority") or "normal").strip()[:40]
                task["updatedAt"] = now
                break
    elif action == "toggleTask":
        item_id = str(body.get("id") or "")
        for task in workspace.get("tasks", []):
            if task.get("id") == item_id:
                task["done"] = not bool(task.get("done"))
                task["status"] = "done" if task["done"] else "queued"
                task["updatedAt"] = now
                break
    elif action == "startTask":
        item_id = str(body.get("id") or "")
        workspace["activeTaskId"] = item_id
        for task in workspace.get("tasks", []):
            if task.get("done"):
                task["status"] = "done"
            elif task.get("id") == item_id:
                task["status"] = "active"
                task["startedAt"] = now
            elif task.get("status") == "active":
                task["status"] = "queued"
    elif action == "completeTask":
        item_id = str(body.get("id") or workspace.get("activeTaskId") or "")
        for task in workspace.get("tasks", []):
            if task.get("id") == item_id:
                task["done"] = True
                task["status"] = "done"
                task["completedAt"] = now
                task["updatedAt"] = now
                break
        if workspace.get("activeTaskId") == item_id:
            workspace["activeTaskId"] = ""
        if workspace.get("settings", {}).get("taskMode") == "auto":
            for task in workspace.get("tasks", []):
                if not task.get("done"):
                    workspace["activeTaskId"] = task.get("id")
                    task["status"] = "active"
                    task["startedAt"] = now
                    break
    elif action == "deleteTask":
        item_id = str(body.get("id") or "")
        workspace["tasks"] = [x for x in workspace.get("tasks", []) if x.get("id") != item_id]
        if workspace.get("activeTaskId") == item_id:
            workspace["activeTaskId"] = ""
    elif action == "setTaskMode":
        mode = (body.get("mode") or "manual").strip()
        if mode not in ("manual", "single", "auto"):
            return {"error": "Invalid task mode", "_status": 400}
        workspace.setdefault("settings", {})["taskMode"] = mode
    elif action == "addNote":
        title = (body.get("title") or "Untitled note").strip()[:160]
        workspace.setdefault("notes", []).insert(0, {
            "id": str(uuid.uuid4()),
            "title": title or "Untitled note",
            "content": str(body.get("content") or "")[:50000],
            "folder": (body.get("folder") or "General").strip()[:120] or "General",
            "kind": (body.get("kind") or "note").strip()[:40],
            "tags": [str(x).strip()[:40] for x in body.get("tags", []) if str(x).strip()][:12],
            "createdAt": now,
            "updatedAt": now,
            "createdBy": actor,
        })
        workspace["notes"] = workspace["notes"][:300]
    elif action == "updateNote":
        item_id = str(body.get("id") or "")
        for note in workspace.get("notes", []):
            if note.get("id") == item_id:
                # Fields left out keep their saved value (v0.10.1 saves: the editor sent
                # tags: [] and erased them).
                note["title"] = (body.get("title") or note.get("title") or "Untitled note").strip()[:160]
                if "content" in body:
                    note["content"] = str(body.get("content") or "")[:50000]
                if "folder" in body or not note.get("folder"):
                    note["folder"] = (body.get("folder") or "General").strip()[:120] or "General"
                note["kind"] = (body.get("kind") or note.get("kind") or "note").strip()[:40]
                if isinstance(body.get("tags"), list):
                    note["tags"] = [str(x).strip()[:40] for x in body.get("tags", []) if str(x).strip()][:12]
                note["updatedAt"] = now
                break
    elif action == "deleteNote":
        item_id = str(body.get("id") or "")
        workspace["notes"] = [x for x in workspace.get("notes", []) if x.get("id") != item_id]
    elif action == "readFile":
        if not capabilities.get("resourcesRead"):
            return {"error": "This provider connection does not expose readable native files", "_status": 405}
        return _read_workspace_text_file(key, _find_agent_record(key), body.get("path") or "")
    elif action == "previewFileSave":
        if not capabilities.get("resourcesWrite"):
            return {"error": "This provider connection does not allow native file edits", "_status": 405}
        return _preview_workspace_text_file(
            key,
            _find_agent_record(key),
            body.get("path") or "",
            body.get("content") or "",
            create=bool(body.get("create", False)),
        )
    elif action == "saveFile":
        if not capabilities.get("resourcesWrite"):
            return {"error": "This provider connection does not allow native file edits", "_status": 405}
        result = _save_workspace_text_file(
            key,
            _find_agent_record(key),
            body.get("path") or "",
            body.get("content") or "",
            create=False,
            expected_revision=body.get("expectedRevision") or "",
        )
        if not result.get("ok"):
            return result
    elif action == "createFile":
        if not capabilities.get("resourcesWrite"):
            return {"error": "This provider connection does not allow native file edits", "_status": 405}
        result = _save_workspace_text_file(
            key,
            _find_agent_record(key),
            body.get("path") or "",
            body.get("content") or "",
            create=True,
            expected_revision=body.get("expectedRevision") or "",
        )
        if not result.get("ok"):
            return result
    elif action == "deleteFile":
        if not capabilities.get("resourcesWrite"):
            return {"error": "This provider connection does not allow native file edits", "_status": 405}
        result = _delete_workspace_text_file(key, _find_agent_record(key), body.get("path") or "")
        if not result.get("ok"):
            return result
    elif action == "listFileRevisions":
        if not capabilities.get("resourcesRead"):
            return {"error": "This provider connection does not expose readable native files", "_status": 405}
        return _list_workspace_file_revisions(key, _find_agent_record(key), body.get("path") or "")
    elif action == "restoreFileRevision":
        if not capabilities.get("resourcesWrite"):
            return {"error": "This provider connection does not allow native file edits", "_status": 405}
        return _restore_workspace_file_revision(
            key,
            _find_agent_record(key),
            body.get("path") or "",
            body.get("backupId") or "",
        )
    elif action == "saveAgentSkill":
        if not capabilities.get("skills"):
            return {"error": "This provider does not expose editable agent skills", "_status": 405}
        name = (body.get("name") or "").strip()
        content = str(body.get("content") or "")
        if not content:
            content = f"---\nname: {name or 'new-skill'}\ndescription: \"Agent workflow skill.\"\n---\n\n# {name or 'New Skill'}\n\nUse this skill when...\n"
        result = _handle_skill_write(key, name, {"name": name, "content": content, "rootId": body.get("rootId") or "",
                                                 "revision": body.get("revision") or ""})
        if not result.get("ok"):
            return result
    elif action == "deleteAgentSkill":
        if not capabilities.get("skills"):
            return {"error": "This provider does not expose editable agent skills", "_status": 405}
        result = _handle_skill_delete(key, (body.get("name") or "").strip())
        if not result.get("ok"):
            return result
    elif action == "saveLibrarySkill":
        content = str(body.get("content") or "")
        name = (body.get("name") or "").strip()
        if not content:
            content = f"---\nname: {name or 'new-library-skill'}\ndescription: \"Reusable Virtual Office skill.\"\n---\n\n# {name or 'New Library Skill'}\n\nUse this skill when...\n"
        result = _handle_skills_library_create({"name": name, "content": content, "revision": body.get("revision") or ""})
        if not result.get("ok"):
            return result
    elif action == "applyLibrarySkill":
        if not capabilities.get("skills"):
            return {"error": "This provider does not expose installable agent skills", "_status": 405}
        result = _handle_skills_library_apply({
            "skill": (body.get("name") or "").strip(),
            "agentId": key,
            "overwrite": bool(body.get("overwrite", True)),
        })
        if not result.get("ok") and not result.get("exists"):
            return result
    elif action == "saveAgentSkillToLibrary":
        if not capabilities.get("skills"):
            return {"error": "This provider does not expose editable agent skills", "_status": 405}
        result = _handle_skills_library_save_from_agent({
            "skill": (body.get("name") or "").strip(),
            "agentId": key,
            "overwrite": bool(body.get("overwrite", False)),
        })
        if not result.get("ok"):
            return result
    elif action == "updateSettings":
        settings = workspace.setdefault("settings", {})
        for field in ("taskMode", "heartbeatMinutes", "cronEnabled", "displayName", "branch", "leaderboardPoints"):
            if field in body:
                settings[field] = body.get(field)
        if "leaderboardPoints" in body:
            try:
                with _json_file_lock(SCORES_FILE):
                    scores = _load_scores_for_write()
                    score_entry = scores["agents"].setdefault(key, {"score": 0, "completed": 0, "streak": 0, "history": []})
                    score_entry["score"] = int(body.get("leaderboardPoints") or 0)
                    _save_scores(scores)
            except Exception:
                pass
        if "heartbeatContent" in body:
            if not payload.get("settings", {}).get("heartbeatApplicable"):
                return {"error": "This provider does not use HEARTBEAT.md", "_status": 400}
            result = _save_workspace_text_file(
                key,
                _find_agent_record(key),
                "HEARTBEAT.md",
                body.get("heartbeatContent") or "",
                create=True,
                expected_revision=body.get("heartbeatRevision") or "",
            )
            if not result.get("ok"):
                return result
        patch = {}
        for field in ("name", "displayName", "role", "branch", "emoji", "color", "model"):
            if field in body:
                patch[field] = str(body.get(field) or "").strip()
        if patch:
            if capabilities.get("profileEdit") and body.get("officeOnly") is not True:
                profile = agent.get("providerAgentId") or agent.get("profile") or agent.get("id")
                native_result = _get_provider_registry().invoke(
                    agent.get("providerKind") or "openclaw",
                    "update_profile",
                    profile,
                    patch,
                )
                if isinstance(native_result, dict) and not native_result.get("ok"):
                    return {
                        "error": native_result.get("error") or "Native profile update failed",
                        "_status": 502,
                    }
            kind = str(agent.get("providerKind") or "")
            if ("model" in patch and kind in agent_permissions.KINDS
                    and patch["model"] != str(agent.get("model") or "").strip()):
                # (a model changed in the agent's settings wins over the one picked in its chat window: latest wins)
                try:
                    agent_permissions.set_run_settings(STATUS_DIR, kind, agent.get("id") or key, model=None)
                except (OSError, ValueError) as exc:
                    print(f"[AGENT] Could not clear the chat model of {key}: {exc}")
            # Agent Studio saves the office copy itself in the same action (officeSaved): writing it here
            # too changed the layout under that save and showed a false "changed somewhere else" (B1).
            if body.get("officeSaved") is not True:
                _update_office_config_agent(key, patch)
    else:
        return {"error": f"Unknown action: {action}", "_status": 400}

    workspace["updatedAt"] = now
    store[store_key] = workspace
    _save_agent_workspaces(store)
    return _get_agent_workspace_payload(key)


def _agent_platform_comm_skill_content():
    office_url = f"http://127.0.0.1:{PORT}"
    return '''---
name: AgentPlatform-to-AgentPlatform_Communications
description: "Talk to agents on OpenClaw, Hermes, or other Virtual Office-connected platforms through the office communication layer."
---

# AgentPlatform-to-AgentPlatform Communications

Use this when you need to send a message, question, handoff, or task note to another agent in My Virtual Office, including agents from other platforms.

## Rule

Do **not** bypass the office with a direct CLI/private channel when the conversation should be visible to the office. Send through the Virtual Office communication endpoint so the interaction is logged for later chat bubbles, review, and cross-platform history.

## Endpoint

Default local endpoint:

```bash
POST {office_url}/api/agent-platform-communications/send
```

If Virtual Office runs elsewhere, use that office base URL.

## Message format

```json
{
  "fromAgentId": "<your office agent id>",
  "toAgentId": "<target office agent id>",
  "message": "<clear message to the target agent>",
  "conversationId": "<optional stable thread id>",
  "metadata": {"topic": "optional"}
}
```

Office agent IDs look like:

- `main`, `ops`, `research` for OpenClaw agents
- `hermes-default` or `hermes-<profile>` for Hermes agents

## Curl example

```bash
curl -sS -X POST {office_url}/api/agent-platform-communications/send \
  -H 'Content-Type: application/json' \
  -d '{
    "fromAgentId":"main",
    "toAgentId":"hermes-default",
    "message":"Hi Hermes, can you review this idea and reply with your take?"
  }'
```

## Response

The response contains the target agent reply and office log IDs:

```json
{
  "ok": true,
  "conversationId": "...",
  "messageId": "...",
  "replyMessageId": "...",
  "reply": "..."
}
```

## Safety

- Keep private data minimal.
- Do not request config, credential, network, or infrastructure changes unless the office owner explicitly approved them.
- Use a clear `conversationId` when continuing the same topic.
- If the endpoint fails, report the error instead of silently using an offscreen private channel.
'''.replace("{office_url}", office_url)


