_PROVIDER_REGISTRY = None


# OpenClaw's folder as its gateway reports it (config.get: where its openclaw.json is), per gateway, for a few minutes.
_OPENCLAW_REPORTED_HOME = {"key": None, "home": "", "at": 0.0}
_OPENCLAW_REPORTED_HOME_TTL = 300.0
_OPENCLAW_GATEWAY_PATH_FIX = (
    "Set VO_OPENCLAW_GATEWAY_PATH to OpenClaw's folder as the gateway's machine sees it (for example "
    "/home/you/.openclaw, the folder with openclaw.json), then restart the office."
)


def _openclaw_home_of_config_path(path):
    """The folder of a reported openclaw.json path ('' unless it is absolute; POSIX or Windows)."""
    text = str(path or "").strip()
    if is_windows_absolute(text):
        import ntpath
        return ntpath.dirname(ntpath.normpath(text))
    if text.startswith("/"):
        return posixpath.dirname(posixpath.normpath(text))
    return ""


def _openclaw_gateway_reported_home(ask=False):
    """OpenClaw's folder in the gateway's own namespace, as the gateway reports it (the folder of its openclaw.json).
    ask=False reads only what an earlier ask learned (no network); '' when unknown or the gateway did not answer."""
    cache = _OPENCLAW_REPORTED_HOME
    try:
        key = _gateway_config_key()
    except Exception:   # (asked while this module is still being defined)
        return ""
    fresh = cache["key"] == key and time.time() - cache["at"] < _OPENCLAW_REPORTED_HOME_TTL
    if not ask or (fresh and cache["home"]):
        return cache["home"] if cache["key"] == key else ""
    result = _gateway_rpc_call("config.get", {}, timeout=10)
    home = _openclaw_home_of_config_path(result.get("path")) if isinstance(result, dict) and result.get("ok") else ""
    cache.update(key=key, home=home, at=time.time())
    return home


def _openclaw_gateway_home_source(ask_gateway=False):
    """(home, source) of ``_openclaw_gateway_home_path``: source is 'setting' (VO_OPENCLAW_GATEWAY_PATH),
    'workspaces' (openclaw.json's agent folders), 'gateway' (the gateway's own answer) or 'office' (the office's own
    OpenClaw folder: right only when the office and the gateway see the same paths)."""
    explicit = str(os.environ.get("VO_OPENCLAW_GATEWAY_PATH") or "").strip()
    if explicit:
        return os.path.abspath(os.path.expanduser(explicit)), "setting"
    inferred = _openclaw_home_from_workspaces()
    if inferred:
        return inferred, "workspaces"
    reported = _openclaw_gateway_reported_home(ask=ask_gateway)
    if reported:
        return reported, "gateway"
    return WORKSPACE_BASE, "office"


def _openclaw_gateway_home_problem(home, source):
    """Why a new agent's folder must not be made under ``home`` ('' when it may): never at the top of a disk, and
    from Docker never the container's own mount point when nothing said where OpenClaw's folder is on its machine."""
    text = str(home or "").strip()
    top = text in ("", "/") or bool(re.fullmatch(r"[A-Za-z]:[\\/]*", text))
    if top or (source == "office" and _running_in_docker()):
        why = (f"OpenClaw's folder on the gateway's machine would be {text or 'unknown'}, the top of the disk" if top else
               "The office could not work out where OpenClaw's folder is on the gateway's machine (its agents' folders "
               "are not named workspace or workspace-<id>, and the gateway did not say)")
        return f"The agent was not created: {why}. {_OPENCLAW_GATEWAY_PATH_FIX}"
    return ""


def _openclaw_gateway_home_path(ask_gateway=False):
    """Return the OpenClaw home path as seen by the external Gateway.

    Docker commonly mounts the host OpenClaw home at ``/openclaw``. Native
    agent creation is executed by the host Gateway, so workspace paths passed
    to ``agents.create`` must use the host namespace. Prefer an explicit
    deployment override, then infer that home from an existing native
    workspace recorded in ``openclaw.json``, then the gateway's own answer
    (``ask_gateway``: ask it now; otherwise only what it said before).
    """
    return _openclaw_gateway_home_source(ask_gateway)[0]


def _openclaw_home_from_workspaces():
    """OpenClaw's folder inferred from openclaw.json's agent folders named workspace / workspace-<id> ('' if none)."""

    config_path = os.path.join(WORKSPACE_BASE, "openclaw.json")
    try:
        with open(config_path, "r", encoding="utf-8") as handle:
            configured = _openclaw_agent_rows(json.load(handle))
    except (OSError, ValueError, TypeError, AttributeError):
        configured = []

    ordered = sorted(
        (item for item in configured if isinstance(item, dict)),
        key=lambda item: 0 if str(item.get("id") or "") == "main" else 1,
    )
    for item in ordered:
        workspace = str(item.get("workspace") or "").strip()
        if not os.path.isabs(workspace):
            continue
        basename = os.path.basename(os.path.normpath(workspace))
        if basename == "workspace" or basename.startswith("workspace-"):
            return os.path.dirname(os.path.normpath(workspace))
    return ""


def _provider_registry_context():
    """Build lazy callbacks so providers never import the HTTP server."""
    def gateway_test(config=None):
        # Agent discovery happens while this large legacy module is still being
        # defined. Defer the real network probe until the endpoint layer exists
        # instead of caching a startup NameError in provider conformance.
        tester = globals().get("_test_openclaw_gateway_config")
        if callable(tester):
            return tester(config)
        openclaw_cfg = config if isinstance(config, dict) else (VO_CONFIG.get("openclaw", {}) or {})
        return {
            "ok": False,
            "installed": True,
            "authOk": bool(openclaw_cfg.get("gatewayToken") or os.environ.get("VO_GATEWAY_TOKEN") or os.environ.get("OPENCLAW_GATEWAY_TOKEN")),
            "deferred": True,
            "error": "OpenClaw Gateway health probe is deferred until server initialization completes",
        }

    return {
        "config": VO_CONFIG,
        "workspaceBase": WORKSPACE_BASE,
        "gatewayWorkspaceBase": _openclaw_gateway_home_path(),
        "statusDir": STATUS_DIR,
        "gatewayTest": gateway_test,
        "openclawCreate": lambda body: _legacy_openclaw_agent_create(body),
        "openclawDelete": lambda profile: _legacy_openclaw_agent_delete(profile),
        "openclawInterrupt": lambda profile: (
            {"ok": True, "interrupted": True}
            if _wf_abort_task_session(f"agent:{profile}:main")
            else {"ok": False, "error": f"No active OpenClaw run for {profile}"}
        ),
        "openclawSend": lambda profile, message, **kwargs: {
            "ok": True,
            "reply": _wf_call_agent_ws(
                profile,
                message,
                int(kwargs.get("timeout_sec") or kwargs.get("timeoutSec") or 600),
                session_key=kwargs.get("session_key") or kwargs.get("sessionKey"),
            ),
        },
        "hermesSend": lambda agent, message, **kwargs: _handle_hermes_chat({
            "agentId": (agent or {}).get("id") or (agent or {}).get("statusKey") or (agent or {}).get("profile"),
            "message": message,
            "timeoutSec": int(kwargs.get("timeout_sec") or kwargs.get("timeoutSec") or 600),
            "sessionId": kwargs.get("session_id") or kwargs.get("sessionId") or "",
            "_onProgress": kwargs.get("on_progress") or kwargs.get("onProgress"),
        }),
        "hermesInterrupt": lambda profile: _handle_hermes_interrupt({"agentId": profile}),
        "sessionList": lambda profile, limit=40: handle_chat_sessions_list(profile, limit=limit)[0],
        "applyAgentPermissions": lambda kind, agent, provider: _apply_agent_permissions(kind, agent, provider),
    }


def _get_provider_registry():
    global _PROVIDER_REGISTRY
    if _PROVIDER_REGISTRY is None:
        _PROVIDER_REGISTRY = build_provider_registry(_provider_registry_context())
    return _PROVIDER_REGISTRY


_PROVIDER_HEALTH_MAX_AGE = _env_int("VO_PROVIDER_HEALTH_MAX_AGE_SEC", 90, minimum=0, maximum=3600)


def _registry_health_manifests(registry):
    """Manifests with health, reusing recent results (BE-24). Accepts older registries."""
    try:
        return registry.manifests(include_health=True, max_age=_PROVIDER_HEALTH_MAX_AGE)
    except TypeError:
        return registry.manifests(include_health=True)


def _reset_provider_registry():
    global _PROVIDER_REGISTRY
    _PROVIDER_REGISTRY = None
    return _get_provider_registry()


DISCOVERY_CACHE_FILE = os.path.join(STATUS_DIR, "provider-discovery-cache.json")
_DISCOVERY_CACHE_LOCK = threading.Lock()
_DISCOVERY_CACHE_FIELDS = {
    "id", "statusKey", "providerAgentId", "profile", "name", "emoji", "role",
    "model", "provider", "gateway", "workspace", "home", "lastActiveAt",
    "providerKind", "providerId", "providerType", "providerManifestVersion",
    "providerConnectionId", "capabilities", "nativeCapabilities", "connectionModes",
    "source", "cliAvailable", "apiAvailable", "createdAt", "lastSeenAt", "offlineSince",
    "resourceAccess", "resourceAccessRequested", "resourcesReadable", "resourcesWritable",
    "resourceMountSource", "resourceMountReason", "workspaceTransport",
    "localProfile", "selectionAliases",
}


def _discovery_agent_key(agent):
    if (agent or {}).get("providerTransport") == "serve":
        # Two `hermes serve` connections can both have a "default" profile: key by office id.
        return ("hermes-serve", str((agent or {}).get("id") or ""))
    return (
        str((agent or {}).get("providerKind") or (agent or {}).get("providerId") or "openclaw"),
        str((agent or {}).get("providerAgentId") or (agent or {}).get("profile") or (agent or {}).get("id") or ""),
    )


def _cache_safe_discovered_agent(agent):
    item = {key: agent.get(key) for key in _DISCOVERY_CACHE_FIELDS if key in agent}
    item["available"] = bool(agent.get("available", True))
    item["connectionState"] = str(agent.get("connectionState") or ("connected" if item["available"] else "offline"))
    return item


def _load_discovery_cache():
    try:
        with open(DISCOVERY_CACHE_FILE, "r", encoding="utf-8") as handle:
            data = json.load(handle)
        rows = data.get("agents") if isinstance(data, dict) else []
        return [row for row in rows if isinstance(row, dict)]
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return []


def _save_discovery_cache(agents):
    payload = {
        "version": 1,
        "updatedAt": datetime.now(timezone.utc).isoformat(),
        "agents": [_cache_safe_discovered_agent(agent) for agent in agents],
    }
    data_owner.makedirs(os.path.dirname(DISCOVERY_CACHE_FILE), exist_ok=True)
    _atomic_write_text(DISCOVERY_CACHE_FILE, json.dumps(payload, indent=2) + "\n", mode=0o600)
    private_files.tighten(DISCOVERY_CACHE_FILE)


def _forget_discovered_agent(provider_kind, provider_agent_id):
    target = (str(provider_kind or "openclaw"), str(provider_agent_id or ""))
    with _DISCOVERY_CACHE_LOCK:
        rows = [row for row in _load_discovery_cache() if _discovery_agent_key(row) != target]
        _save_discovery_cache(rows)


def _discover_roster():
    now = datetime.now(timezone.utc).isoformat()
    registry = _get_provider_registry()
    live = registry.discover_agents()
    try:
        manifest_health = {
            str(item.get("id") or ""): item
            for item in _registry_health_manifests(registry)
            if isinstance(item, dict) and item.get("id")
        }
    except Exception:
        manifest_health = {}
    gateway_agent = _hermes_platform_roster_agent()
    if gateway_agent:
        gateway_key = gateway_agent.get("statusKey") or gateway_agent.get("id")
        if not any(
            gateway_key in (row.get("id"), row.get("statusKey"), row.get("providerAgentId"))
            for row in live
        ):
            live.append(gateway_agent)
    # Hermes `hermes serve` connections: one agent per profile (design 2.10).
    try:
        serve_rows = [] if _pl_owns() else agent_providers.discovery_rows()
    except Exception as exc:
        print(f"[agent-providers] serve discovery skipped: {exc}")
        serve_rows = []
    if _pl_owns():
        # OpenClaw and Hermes agents come from the layer (its gateways' agents.list, its Hermes profiles), in the places
        # 0.10 gave them (OpenClaw first, Hermes after the other providers), so the demo shows the same agents
        live = [row for row in live if not isinstance(row, dict)
                or str(row.get("providerKind") or row.get("providerId") or "openclaw") != "openclaw"]
        layer_rows = provider_layer_ids.roster_rows(skip={str(row.get("id") or "") for row in live})
        live = [row for row in layer_rows if row.get("providerKind") == "openclaw"] + live
        hidden = _pl_hidden_hermes()
        serve_rows = [row for row in layer_rows if row.get("providerKind") != "openclaw" and row.get("id") not in hidden]
    live_ids = {str(row.get("id") or "") for row in live}
    live.extend(row for row in serve_rows if str(row.get("id") or "") not in live_ids)
    merged = []
    live_keys = set()
    live_agent_ids = set()
    openclaw_discovery_succeeded = any(
        str(row.get("providerKind") or row.get("providerId") or "openclaw") == "openclaw"
        for row in live
        if isinstance(row, dict)
    )
    for row in live:
        item = dict(row)
        # Names, emoji and roles come from agent-editable files: keep them plain text.
        for field, limit in (("name", 60), ("emoji", 16), ("role", 80)):
            if field in item and item.get(field) is not None:
                item[field] = clean_display_text(item.get(field), limit)
        provider_kind = str(item.get("providerKind") or item.get("providerId") or "openclaw")
        provider_manifest = manifest_health.get(provider_kind) or {}
        capabilities = provider_manifest.get("capabilities") if isinstance(provider_manifest.get("capabilities"), dict) else {}
        health = provider_manifest.get("health") if isinstance(provider_manifest.get("health"), dict) else {}
        health_authoritative = bool(capabilities.get("health")) and bool(health)
        if item.get("providerTransport") in ("serve", "layer"):
            # `hermes serve` rows carry their own connection status; the provider manifest
            # health is the legacy local CLI probe (binary + home), which a serve-only
            # install never has, so it must not take these agents offline.
            own_state = str(row.get("connectionState") or "").strip()
            item["available"] = row.get("available") is not False
            item["connectionState"] = "connected" if item["available"] else (
                own_state if own_state and own_state != "connected" else "offline")
        elif provider_kind == "hermes" and item.get("apiAvailable") and "api" in (item.get("connectionModes") or []):
            # A Hermes API-server row (0.7.x hermes.connections) is listed only after its API server answered /health
            # during this discovery, so that answer is its health. The manifest health is the local CLI probe, which an
            # office without a Hermes CLI (the Docker image ships none) never passes: it must not take these offline.
            item["available"] = row.get("available") is not False
            item["connectionState"] = "connected" if item["available"] else "offline"
        else:
            provider_connected = (
                bool(health.get("ok")) and health.get("authOk") is not False
            ) if health_authoritative else True
            item["available"] = bool(row.get("available", True)) and provider_connected
            item["connectionState"] = "connected" if item["available"] else str(health.get("connectionState") or "offline")
        item["lastSeenAt"] = now
        if item["available"]:
            item.pop("offlineSince", None)
        else:
            item.setdefault("offlineSince", now)
        merged.append(item)
        live_keys.add(_discovery_agent_key(item))
        live_agent_ids.add(str(item.get("id") or ""))
    with _DISCOVERY_CACHE_LOCK:
        for cached in _load_discovery_cache():
            if _discovery_agent_key(cached) in live_keys:
                continue
            # Never two agents with one id (a switched legacy row now lives on its serve profile),
            # and serve agents come only from their connection (it keeps its own offline cache).
            if str(cached.get("id") or "") in live_agent_ids or cached.get("providerTransport") == "serve":
                continue
            # OpenClaw's config is authoritative: once live discovery succeeded,
            # agents deleted outside the office must not return as offline ghosts.
            # Other providers keep their intentional offline history.
            # (with the layer, its id map is the authority once read: an agent it no longer lists is gone)
            layer_read = _pl_owns() and getattr(provider_layer_ids.ids(), "loaded_at", 0) > 0
            if (openclaw_discovery_succeeded or layer_read) and str(cached.get("providerKind") or cached.get("providerId") or "openclaw") == "openclaw":
                continue
            item = dict(cached)
            for field, limit in (("name", 60), ("emoji", 16), ("role", 80)):
                if field in item and item.get(field) is not None:
                    item[field] = clean_display_text(item.get(field), limit)
            item["available"] = False
            item["connectionState"] = "offline"
            item.setdefault("offlineSince", now)
            merged.append(item)
        _save_discovery_cache(merged)
    return merged


def _sync_provider_presence_health(rows, prune=False):
    """Feed discovery connectivity into the independent provider-health plane."""
    agents = [row for row in (rows or []) if isinstance(row, dict)]
    agent_ids = [
        str(row.get("statusKey") or row.get("id") or "").strip()
        for row in agents
        if str(row.get("statusKey") or row.get("id") or "").strip()
    ]
    try:
        gateway_presence.init_agents(agent_ids, prune=prune)
    except Exception:
        pass
    for row in agents:
        agent_id = str(row.get("statusKey") or row.get("id") or "").strip()
        if not agent_id:
            continue
        provider_kind = str(row.get("providerKind") or row.get("providerId") or "openclaw")
        connection_state = str(row.get("connectionState") or ("connected" if row.get("available") is not False else "offline"))
        connected = row.get("available") is not False and connection_state.lower() not in {"offline", "disconnected", "unavailable", "error"}
        callback = getattr(
            gateway_presence,
            "lifecycle_provider_connected" if connected else "lifecycle_provider_disconnected",
            None,
        )
        if not callable(callback):
            continue
        try:
            if connected:
                callback(agent_id, provider_kind, connection_state)
            else:
                callback(agent_id, provider_kind, connection_state, str(row.get("error") or ""))
        except Exception:
            pass

def _initial_roster():
    """Start from the last saved roster so the server can answer at once (BE-08);
    a background refresh replaces it within seconds. First run discovers inline."""
    cached = _load_discovery_cache()
    if cached:
        return cached, 1.0  # non-zero but stale: first get_roster() refreshes in the background
    return _discover_roster(), time.time()


_discovered_roster, _discovered_at = _initial_roster()
DISCOVERY_REFRESH_SEC = 30
_DISCOVERY_REFRESH_LOCK = threading.Lock()
_DISCOVERY_BACKGROUND = {"running": False}
_DISCOVERY_BACKGROUND_LOCK = threading.Lock()


def _run_discovery_refresh():
    global _discovered_roster, _discovered_at
    with _DISCOVERY_REFRESH_LOCK:
        roster = _discover_roster()
        _discovered_roster = roster
        _discovered_at = time.time()
        _sync_provider_presence_health(roster, prune=True)
    try:
        _rebuild_agent_maps()
    except Exception:
        traceback.print_exc()


def _background_discovery_worker():
    try:
        _run_discovery_refresh()
    except Exception:
        traceback.print_exc()
    finally:
        with _DISCOVERY_BACKGROUND_LOCK:
            _DISCOVERY_BACKGROUND["running"] = False


def _refresh_discovery(force=False):
    """Refresh the provider-owned roster.

    Stale-while-revalidate (BE-08): when the roster is older than
    DISCOVERY_REFRESH_SEC a background thread rediscovers and requests keep the
    cached roster. ``force`` (or ``_discovered_at = 0`` after an agent was created
    or deleted) refreshes inline so the caller sees the change.
    """
    if force or _discovered_at == 0:
        _run_discovery_refresh()
        return True
    if time.time() - _discovered_at <= DISCOVERY_REFRESH_SEC:
        return False
    with _DISCOVERY_BACKGROUND_LOCK:
        if _DISCOVERY_BACKGROUND["running"]:
            return False
        _DISCOVERY_BACKGROUND["running"] = True
    threading.Thread(target=_background_discovery_worker, name="roster-refresh", daemon=True).start()
    return False

def get_roster():
    """Get current discovered agent roster."""
    _refresh_discovery()
    return _discovered_roster


def _apply_agent_limit_balanced(agents):
    """Apply product agent limits without hiding entire provider types.

    The old behavior sliced the discovered list, which meant newly added
    providers like Hermes could be detected but never visible in demo/limited
    modes because OpenClaw agents came first. This keeps licensing limits while
    trying to include at least one agent from each detected provider.
    """
    agent_limit = get_agent_limit()
    if agent_limit <= 0 or len(agents) <= agent_limit:
        return agents

    selected = []
    selected_keys = set()

    def key_for(a):
        return a.get("key") or a.get("statusKey") or a.get("agentId") or a.get("id")

    # First pass: one representative from each provider. Prefer a healthy
    # native streaming/API identity over a buffered compatibility alias, while
    # retaining discovery order as the stable tie-breaker.
    provider_order = []
    provider_best = {}
    provider_scores = {}
    for index, agent in enumerate(agents):
        provider = agent.get("providerKind", "openclaw")
        if provider not in provider_best:
            provider_order.append(provider)
        capabilities = agent.get("capabilities") if isinstance(agent.get("capabilities"), dict) else {}
        modes = {str(value).lower() for value in (agent.get("connectionModes") or [])}
        score = (
            1 if agent.get("available") is not False else 0,
            1 if agent.get("apiAvailable") or "api" in modes else 0,
            1 if capabilities.get("streaming") else 0,
            1 if capabilities.get("tools") else 0,
            -index,
        )
        if provider not in provider_scores or score > provider_scores[provider]:
            provider_scores[provider] = score
            provider_best[provider] = agent

    for provider in provider_order:
        agent = provider_best[provider]
        k = key_for(agent)
        selected.append(agent)
        selected_keys.add(k)
        if len(selected) >= agent_limit:
            return selected

    # Fill remaining slots using original order.
    for agent in agents:
        k = key_for(agent)
        if k in selected_keys:
            continue
        selected.append(agent)
        selected_keys.add(k)
        if len(selected) >= agent_limit:
            break
    return selected

# Build compatibility maps from discovery (these update on refresh)
def _build_agent_info():
    return {a["statusKey"]: {"id": a["id"], "emoji": a["emoji"], "name": a["name"], "branch": "", "providerKind": a.get("providerKind", "openclaw")} for a in get_roster()}
def _build_agent_workspaces():
    result = {}
    for a in get_roster():
        if a.get("providerKind", "openclaw") != "openclaw":
            result[a["statusKey"]] = a.get("home") or a.get("workspace") or ""
        else:
            result[a["statusKey"]] = get_agent_workspace_dir(WORKSPACE_BASE, a["id"]).replace(WORKSPACE_BASE + "/", "") if a["workspace"].startswith(WORKSPACE_BASE) else os.path.basename(a["workspace"])
    return result
def _build_agent_session_ids():
    return {
        a["statusKey"]: (
            a.get("providerAgentId")
            if a.get("providerKind", "openclaw") != "openclaw"
            else get_agent_session_id(a["id"])
        )
        for a in get_roster()
    }

# Compatibility properties (lazily rebuilt)
@property
def _agent_info_prop(self):
    return _build_agent_info()

# For now, build once and provide as module-level (callers use these directly)
AGENT_INFO = _build_agent_info()
AGENT_WORKSPACES = _build_agent_workspaces()
AGENT_SESSION_IDS = _build_agent_session_ids()

def _patch_default_config_agents(config_str):
    """Replace hardcoded agents in default config with actual roster agents.
    Returns JSON string with agents patched from the live discovery roster."""
    try:
        cfg = json.loads(config_str)
    except Exception:
        return config_str
    roster = get_roster()
    if not roster:
        return config_str
    # Build agent entries from roster with random/seeded appearances
    patched_agents = []
    for a in roster:
        agent_id = a.get("statusKey") or a.get("id", "main")
        name = a.get("name") or agent_id
        # Seed a deterministic hash for random appearance
        h = int(hashlib.md5(agent_id.encode()).hexdigest(), 16)
        skin_tones = ['#ffcc80','#d4a574','#c68642','#e8b88a','#fddcb5','#f5d0b0','#8d5524']
        hair_styles = ['short','medium','long','curly','spiky','buzz','wavy']
        hair_colors = ['#1a1a1a','#333333','#5d4037','#616161','#bf360c','#dcc282','#ffd700','#263238']
        desk_items = ['trophy','envelope','calendar','chart','plans','checklist','files','ruler','money','marker']
        gender = 'F' if (h >> 2) % 2 == 0 else 'M'
        patched_agents.append({
            "id": agent_id,
            "name": name,
            "role": a.get("role", "AI assistant"),
            "emoji": a.get("emoji", "🤖"),
            "color": _AGENT_COLORS_LIST[len(patched_agents) % len(_AGENT_COLORS_LIST)] if len(patched_agents) < len(_AGENT_COLORS_LIST) else '#607d8b',
            "gender": gender,
            "branch": "UNASSIGNED",
            "statusKey": agent_id,
            "appearance": {
                "skinTone": skin_tones[h % len(skin_tones)],
                "hairStyle": hair_styles[(h >> 3) % len(hair_styles)] if gender == 'M' else hair_styles[(h >> 3) % 3 + 2],
                "hairColor": hair_colors[(h >> 5) % len(hair_colors)],
                "hairHighlight": None,
                "eyebrowStyle": "thin" if gender == 'F' else "thick",
                "eyeColor": "#212121",
                "facialHair": None, "facialHairColor": None,
                "headwear": None, "headwearColor": None,
                "glasses": None, "glassesColor": None,
                "costume": None,
                "heldItem": None,
                "deskItem": desk_items[(h >> 8) % len(desk_items)]
            }
        })
    cfg["agents"] = patched_agents
    return json.dumps(cfg)

# Color palette used for default config agent patching
_AGENT_COLORS_LIST = ['#ffd700','#d32f2f','#1976d2','#388e3c','#f9a825','#e65100','#00897b','#7b1fa2','#6d4c41','#5c6bc0','#78909c','#4caf50','#00bcd4','#e91e90','#ff6d00','#795548','#607d8b','#9c27b0','#009688','#ff5722']

def _rebuild_agent_maps():
    global AGENT_INFO, AGENT_WORKSPACES, AGENT_SESSION_IDS
    AGENT_INFO = _build_agent_info()
    AGENT_WORKSPACES = _build_agent_workspaces()
    AGENT_SESSION_IDS = _build_agent_session_ids()


def refresh_agent_maps(force_discovery=False):
    """Refresh discovery when requested, then update compatibility maps."""
    _refresh_discovery(force=force_discovery)
    _rebuild_agent_maps()


def _agent_display_label(agent_id_or_key):
    """Return a friendly VO label for an agent id/status key without exposing internals."""
    if not agent_id_or_key:
        return ""
    needle = str(agent_id_or_key)
    for a in get_roster():
        if needle in (a.get("id"), a.get("statusKey")):
            name = a.get("name") or needle
            emoji = a.get("emoji") or ""
            return f"{name} {emoji}".strip()
    return needle


def _agent_id_from_session_key(session_key):
    """Parse OpenClaw session keys like agent:<agentId>:<bucket>."""
    if not session_key:
        return ""
    m = re.match(r"^agent:([^:]+):", str(session_key))
    return m.group(1) if m else ""


def _is_hermes_agent(agent_id_or_key):
    needle = str(agent_id_or_key or "")
    for a in get_roster():
        aliases = a.get("selectionAliases") if isinstance(a.get("selectionAliases"), list) else []
        if needle in (a.get("id"), a.get("statusKey"), a.get("providerAgentId")) or needle in {str(value) for value in aliases}:
            return a.get("providerKind") == "hermes"
    return needle.startswith("hermes:") or needle.startswith("hermes-")


def _parse_iso_epoch_ms(value):
    """Convert ISO timestamps or epoch-ish values to browser-friendly epoch ms."""
    if not value:
        return 0
    if isinstance(value, (int, float)):
        return int(value if value > 1e12 else value * 1000)
    try:
        raw = str(value)
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        return int(dt.timestamp() * 1000)
    except Exception:
        return 0


def _utc_now_iso():
    return datetime.now(timezone.utc).isoformat()


def _epoch_to_utc_iso(epoch):
    try:
        return datetime.fromtimestamp(float(epoch), tz=timezone.utc).isoformat()
    except Exception:
        return ""


def _format_time_local(ts):
    """Convert ISO timestamp or epoch ms to HH:MM AM/PM in the configured local zone."""
    try:
        if isinstance(ts, (int, float)):
            dt = datetime.fromtimestamp(ts / 1000 if ts > 1e12 else ts, tz=timezone.utc)
        elif isinstance(ts, str):
            if not ts.strip():
                return ""
            dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        else:
            return ""
        local_tz = ZoneInfo(os.environ.get("VO_TIMEZONE") or os.environ.get("TZ") or "UTC")
        return dt.astimezone(local_tz).strftime("%I:%M %p").lstrip("0")
    except Exception:
        return ""


def _read_tail_text(path, initial_bytes=64 * 1024, max_bytes=2 * 1024 * 1024, min_lines=20):
    """Read a complete-line tail from large JSONL files."""
    if not path or not os.path.exists(path):
        return ""
    try:
        with open(path, "rb") as fb:
            fb.seek(0, 2)
            fsize = fb.tell()
            tail_size = min(initial_bytes, fsize)
            while True:
                start = max(0, fsize - tail_size)
                fb.seek(start)
                tail_data = fb.read().decode("utf-8", errors="replace")
                if start > 0:
                    nl = tail_data.find("\n")
                    if nl >= 0:
                        tail_data = tail_data[nl + 1:]
                complete_lines = [x for x in tail_data.split("\n") if x.strip()]
                if start == 0 or len(complete_lines) >= min_lines or tail_size >= min(max_bytes, fsize):
                    return tail_data
                tail_size = min(tail_size * 4, max_bytes, fsize)
    except Exception:
        return ""


def _openclaw_session_paths(agent_id, session_key=None):
    """Resolve the active transcript and matching trajectory file for an agent session."""
    if not agent_id:
        return None, None, {}
    sessions_dir = os.path.join(WORKSPACE_BASE, f"agents/{agent_id}/sessions")
    sessions_json_path = os.path.join(sessions_dir, "sessions.json")
    session_info = {}
    selected_key = session_key or ""
    try:
        with open(sessions_json_path, "r") as f:
            sessions = json.load(f)
        if session_key and isinstance(sessions.get(session_key), dict):
            session_info = sessions.get(session_key) or {}
        if not session_info:
            best_ts = -1
            for skey, val in sessions.items():
                if not isinstance(val, dict):
                    continue
                ts = val.get("updatedAt", 0)
                if ts > best_ts:
                    best_ts = ts
                    session_info = val
                    selected_key = skey
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        session_info = {}

    if session_info and selected_key:
        session_info = dict(session_info)
        session_info.setdefault("key", selected_key)
        session_info.setdefault("sessionKey", selected_key)
    session_id = str(session_info.get("sessionId") or "")
    jsonl_file = os.path.join(sessions_dir, f"{session_id}.jsonl") if session_id else None
    trajectory_file = os.path.join(sessions_dir, f"{session_id}.trajectory.jsonl") if session_id else None
    if jsonl_file and not os.path.exists(jsonl_file):
        jsonl_file = None
    if trajectory_file and not os.path.exists(trajectory_file):
        trajectory_file = None
    return jsonl_file, trajectory_file, session_info


def _safe_tool_arguments(value):
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            if isinstance(parsed, dict):
                return parsed
        except Exception:
            return {"value": value}
    return {}


def _limit_tool_payload(value, limit=2400):
    if value is None:
        return ""
    if isinstance(value, (dict, list)):
        try:
            value = json.dumps(value, ensure_ascii=False)
        except Exception:
            value = str(value)
    value = str(value)
    if len(value) > limit:
        return value[:limit] + f"\n\n... [truncated - {len(value)} chars total] ..."
    return value


_TRAJECTORY_THREAD_CACHE = {}
_TRAJECTORY_THREAD_CACHE_LOCK = threading.Lock()
_CODEX_COMMENTARY_CACHE = {}
_CODEX_COMMENTARY_CACHE_LOCK = threading.Lock()
_TRAJECTORY_CACHE_MAX_RUNS = 500
_TRAJECTORY_CACHE_MAX_FILES = 64
_CODEX_COMMENTARY_MAX_MESSAGES = 400
_CODEX_COMMENTARY_MAX_FILES = 64


def _trajectory_run_metadata(trajectory_file):
    """Incrementally retain run/thread boundaries for long OpenClaw sessions."""
    if not trajectory_file or not os.path.isfile(trajectory_file):
        return {}
    try:
        size = os.path.getsize(trajectory_file)
    except OSError:
        return {}

    with _TRAJECTORY_THREAD_CACHE_LOCK:
        cached = _TRAJECTORY_THREAD_CACHE.get(trajectory_file) or {"offset": 0, "runs": {}, "version": 2}
        if size < int(cached.get("offset") or 0) or cached.get("version") != 2:
            cached = {"offset": 0, "runs": {}, "version": 2}
        offset = int(cached.get("offset") or 0)
        runs = {
            str(key): dict(value)
            for key, value in (cached.get("runs") or {}).items()
            if key and isinstance(value, dict)
        }
        try:
            with open(trajectory_file, "rb") as stream:
                stream.seek(offset)
                for raw_line in stream:
                    if b'"runId"' not in raw_line and b'"run_id"' not in raw_line:
                        continue
                    try:
                        event = json.loads(raw_line.decode("utf-8", errors="replace"))
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        continue
                    data = event.get("data") if isinstance(event.get("data"), dict) else {}
                    run_id = str(event.get("runId") or data.get("runId") or "")
                    thread_id = str(data.get("threadId") or data.get("thread_id") or "")
                    if not run_id:
                        continue
                    run = runs.setdefault(run_id, {
                        "runId": run_id,
                        "threadId": "",
                        "firstMs": 0,
                        "lastMs": 0,
                        "startedAt": 0,
                        "endedAt": 0,
                    })
                    if thread_id:
                        run["threadId"] = thread_id
                    epoch_ms = _parse_iso_epoch_ms(event.get("ts") or event.get("timestamp"))
                    if epoch_ms:
                        if not run.get("firstMs") or epoch_ms < int(run.get("firstMs") or 0):
                            run["firstMs"] = epoch_ms
                        if epoch_ms > int(run.get("lastMs") or 0):
                            run["lastMs"] = epoch_ms
                        event_type = str(event.get("type") or "")
                        if event_type == "session.started":
                            run["startedAt"] = epoch_ms
                        elif event_type == "session.ended":
                            run["endedAt"] = epoch_ms
                next_offset = stream.tell()
        except OSError:
            return runs
        if len(runs) > _TRAJECTORY_CACHE_MAX_RUNS:  # BE-33: bounded, keep the most recent runs
            keep = sorted(runs.items(), key=lambda item: int((item[1] or {}).get("lastMs") or 0))[-_TRAJECTORY_CACHE_MAX_RUNS:]
            runs = dict(keep)
        _TRAJECTORY_THREAD_CACHE.pop(trajectory_file, None)
        _TRAJECTORY_THREAD_CACHE[trajectory_file] = {"offset": next_offset, "runs": runs, "version": 2}
        while len(_TRAJECTORY_THREAD_CACHE) > _TRAJECTORY_CACHE_MAX_FILES:
            _TRAJECTORY_THREAD_CACHE.pop(next(iter(_TRAJECTORY_THREAD_CACHE)), None)
        return {key: dict(value) for key, value in runs.items()}


def _trajectory_thread_map(trajectory_file):
    """Return the retained run-to-Codex-thread mapping."""
    return {
        run_id: str(metadata.get("threadId") or "")
        for run_id, metadata in _trajectory_run_metadata(trajectory_file).items()
        if metadata.get("threadId")
    }


def _trajectory_run_windows(run_metadata):
    """Build non-overlapping timestamp windows used to scope rollout recovery."""
    prepared = []
    for run_id, raw in (run_metadata or {}).items():
        if not run_id or not isinstance(raw, dict):
            continue
        start_ms = int(raw.get("startedAt") or raw.get("firstMs") or 0)
        if not start_ms or not raw.get("threadId"):
            continue
        prepared.append({**raw, "runId": str(run_id), "threadId": str(raw.get("threadId") or ""), "startMs": start_ms})
    prepared.sort(key=lambda run: (run.get("startMs") or 0, run.get("runId") or ""))
    now_ms = int(time.time() * 1000) + 5000
    windows = {}
    for index, run in enumerate(prepared):
        next_start = int(prepared[index + 1].get("startMs") or 0) if index + 1 < len(prepared) else 0
        explicit_end = int(run.get("endedAt") or 0)
        if explicit_end:
            end_ms = explicit_end
        elif next_start:
            end_ms = max(run["startMs"], next_start - 1)
        else:
            end_ms = max(now_ms, int(run.get("lastMs") or 0), run["startMs"])
        if next_start:
            end_ms = min(end_ms, max(run["startMs"], next_start - 1))
        windows[run["runId"]] = {
            "runId": run["runId"],
            "threadId": run["threadId"],
            "startMs": run["startMs"],
            "endMs": end_ms,
        }
    return windows


def _codex_rollout_commentary_items(rollout_file, thread_id):
    """Incrementally retain every public commentary item in a Codex rollout."""
    if not rollout_file or not os.path.isfile(rollout_file):
        return []
    try:
        size = os.path.getsize(rollout_file)
    except OSError:
        return []

    with _CODEX_COMMENTARY_CACHE_LOCK:
        cached = _CODEX_COMMENTARY_CACHE.get(rollout_file) or {"offset": 0, "messages": [], "ids": set()}
        if size < int(cached.get("offset") or 0):
            cached = {"offset": 0, "messages": [], "ids": set()}
        offset = int(cached.get("offset") or 0)
        messages = list(cached.get("messages") or [])
        seen = set(cached.get("ids") or set())
        try:
            with open(rollout_file, "rb") as stream:
                stream.seek(offset)
                for index, raw_line in enumerate(stream):
                    if b'"commentary"' not in raw_line:
                        continue
                    try:
                        record = json.loads(raw_line.decode("utf-8", errors="replace"))
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        continue
                    if record.get("type") != "response_item":
                        continue
                    payload = record.get("payload") if isinstance(record.get("payload"), dict) else {}
                    if payload.get("type") != "message" or payload.get("role") != "assistant" or payload.get("phase") != "commentary":
                        continue
                    parts = []
                    content = payload.get("content")
                    if isinstance(content, str):
                        parts.append(content)
                    elif isinstance(content, list):
                        for item in content:
                            if not isinstance(item, dict):
                                continue
                            text = item.get("text")
                            if isinstance(text, str) and text.strip():
                                parts.append(text)
                    text = "\n".join(parts).strip()
                    if not text:
                        continue
                    ts = record.get("timestamp") or record.get("ts") or ""
                    item_id = str(payload.get("id") or f"{thread_id}:{ts}:{offset}:{index}")
                    commentary_id = f"codex-commentary:{item_id}"
                    if commentary_id in seen:
                        continue
                    seen.add(commentary_id)
                    messages.append({
                        "id": commentary_id,
                        "role": "assistant",
                        "text": text,
                        "ts": ts,
                        "epochMs": _parse_iso_epoch_ms(ts),
                        "source": "codex-commentary",
                    })
                next_offset = stream.tell()
        except OSError:
            return messages
        messages.sort(key=lambda message: message.get("epochMs") or 0)
        if len(messages) > _CODEX_COMMENTARY_MAX_MESSAGES:  # BE-33: bounded per rollout
            messages = messages[-_CODEX_COMMENTARY_MAX_MESSAGES:]
            seen = {message.get("id") for message in messages}
        _CODEX_COMMENTARY_CACHE.pop(rollout_file, None)
        _CODEX_COMMENTARY_CACHE[rollout_file] = {"offset": next_offset, "messages": messages, "ids": seen}
        while len(_CODEX_COMMENTARY_CACHE) > _CODEX_COMMENTARY_MAX_FILES:
            _CODEX_COMMENTARY_CACHE.pop(next(iter(_CODEX_COMMENTARY_CACHE)), None)
        return [dict(message) for message in messages]


def _codex_rollout_commentary_messages(agent_id, run_metadata, run_id="", max_messages=80):
    """Recover public Codex commentary omitted from OpenClaw chat history.

    Codex labels safe progress updates as assistant messages with
    ``phase=commentary``. Encrypted reasoning records and final answers are
    intentionally excluded.
    """
    if not agent_id or not isinstance(run_metadata, dict):
        return []
    all_windows = _trajectory_run_windows(run_metadata)
    selected_runs = {
        key: value
        for key, value in all_windows.items()
        if not run_id or key == str(run_id)
    }
    if not selected_runs:
        return []

    codex_sessions_dir = os.path.join(
        WORKSPACE_BASE,
        "agents",
        _safe_openclaw_agent_id(agent_id),
        "agent",
        "codex-home",
        "sessions",
    )
    if not os.path.isdir(codex_sessions_dir):
        return []

    messages = []
    seen = set()
    recovered_by_thread = {}
    for thread_id in {window["threadId"] for window in selected_runs.values()}:
        safe_thread_id = re.sub(r"[^a-zA-Z0-9_.-]+", "", thread_id)[:160]
        if not safe_thread_id:
            continue
        candidates = glob.glob(os.path.join(codex_sessions_dir, "**", f"*-{safe_thread_id}.jsonl"), recursive=True)
        if not candidates:
            continue
        rollout_file = max(candidates, key=os.path.getmtime)
        recovered_by_thread[thread_id] = _codex_rollout_commentary_items(rollout_file, safe_thread_id)

    for thread_id, recovered_items in recovered_by_thread.items():
        thread_windows = [window for window in selected_runs.values() if window.get("threadId") == thread_id]
        for recovered in recovered_items:
            commentary_id = str(recovered.get("id") or "")
            if not commentary_id or commentary_id in seen:
                continue
            epoch_ms = int(recovered.get("epochMs") or 0)
            matching = [
                window for window in thread_windows
                if epoch_ms and window["startMs"] <= epoch_ms <= window["endMs"]
            ]
            if not matching:
                continue
            owner = max(matching, key=lambda window: window["startMs"])
            seen.add(commentary_id)
            messages.append({
                **recovered,
                "runId": owner["runId"],
                "runStartedAt": owner["startMs"],
                "runEndedAt": owner["endMs"],
            })

    messages.sort(key=lambda message: message.get("epochMs") or 0)
    return messages[-max_messages:]


def _trajectory_activity_messages(trajectory_file, max_tools=60, agent_id="", run_id="", commentary_only=False):
    """Recover tools and public Codex commentary from OpenClaw activity."""
    tail_data = _read_tail_text(trajectory_file, initial_bytes=256 * 1024, max_bytes=4 * 1024 * 1024, min_lines=80)
    if not tail_data:
        return []

    tools = {}
    order = []
    run_metadata = _trajectory_run_metadata(trajectory_file)
    for line in tail_data.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            continue
        event_type = event.get("type") or ""
        data = event.get("data") if isinstance(event.get("data"), dict) else {}
        event_run_id = str(event.get("runId") or data.get("runId") or "")
        thread_id = str(data.get("threadId") or data.get("thread_id") or "")
        if event_run_id and thread_id:
            run = run_metadata.setdefault(event_run_id, {"runId": event_run_id})
            run["threadId"] = thread_id
        if event_type not in ("tool.call", "tool.result"):
            continue
        if run_id and event_run_id != str(run_id):
            continue
        tool_id = str(data.get("toolCallId") or data.get("tool_call_id") or data.get("itemId") or event.get("id") or "")
        if not tool_id:
            tool_id = f"{event.get('seq', len(order))}:{event_type}"
        if tool_id not in tools:
            tools[tool_id] = {
                "id": tool_id,
                "runId": event.get("runId") or data.get("runId") or "",
                "status": "running",
                "name": data.get("name") or data.get("toolName") or "tool",
                "arguments": {},
                "result": "",
                "error": "",
                "ts": event.get("ts") or "",
                "epochMs": _parse_iso_epoch_ms(event.get("ts")),
                "source": "trajectory",
            }
            order.append(tool_id)
        tool = tools[tool_id]
        if event.get("ts"):
            tool["ts"] = event.get("ts")
            tool["epochMs"] = _parse_iso_epoch_ms(event.get("ts"))
        if event_type == "tool.call":
            tool["status"] = "running"
            tool["name"] = data.get("name") or data.get("toolName") or tool.get("name") or "tool"
            tool["arguments"] = _safe_tool_arguments(data.get("arguments") or data.get("args") or {})
        elif event_type == "tool.result":
            is_error = bool(data.get("isError") or data.get("error"))
            tool["status"] = "error" if is_error else "done"
            tool["name"] = data.get("name") or data.get("toolName") or tool.get("name") or "tool"
            result = data.get("output")
            if result is None:
                result = data.get("result")
            if result is None:
                result = data.get("error")
            if is_error:
                tool["error"] = _limit_tool_payload(result)
            else:
                tool["result"] = _limit_tool_payload(result)

    messages = []
    if not commentary_only:
        for tool_id in order[-max_tools:]:
            tool = tools.get(tool_id)
            if not tool:
                continue
            ts = tool.get("ts") or ""
            messages.append({
                "role": "assistant",
                "text": "",
                "ts": ts,
                "epochMs": tool.get("epochMs") or 0,
                "runId": tool.get("runId") or "",
                "tools": [tool],
                "source": "trajectory",
            })
    if agent_id:
        messages.extend(_codex_rollout_commentary_messages(
            agent_id,
            run_metadata,
            run_id=run_id,
            max_messages=max_tools,
        ))
    messages.sort(key=lambda message: message.get("epochMs") or 0)
    return messages[-max_tools:]


def _session_trajectory_messages(session_key, max_tools=80, run_id="", commentary_only=False):
    agent_id = _agent_id_from_session_key(session_key)
    if not agent_id:
        return []
    _, trajectory_file, _ = _openclaw_session_paths(agent_id, session_key=session_key)
    return _trajectory_activity_messages(
        trajectory_file,
        max_tools=max_tools,
        agent_id=agent_id,
        run_id=run_id,
        commentary_only=commentary_only,
    )


def _get_hermes_agent(agent_id_or_key=None):
    needle = str(agent_id_or_key or "")
    for a in get_roster():
        aliases = a.get("selectionAliases") if isinstance(a.get("selectionAliases"), list) else []
        if a.get("providerKind") == "hermes" and (
            not needle
            or needle in (a.get("id"), a.get("statusKey"), a.get("providerAgentId"), a.get("profile"))
            or needle in {str(value) for value in aliases}
        ):
            return a
    return None


def _is_hermes_gateway_platform_agent(agent_or_id):
    agent = agent_or_id if isinstance(agent_or_id, dict) else _get_hermes_agent(agent_or_id)
    return bool(agent and agent.get("providerKind") == "hermes" and agent.get("providerType") == "gateway-platform")


def _get_codex_agent(agent_id_or_key=None):
    needle = str(agent_id_or_key or "")
    for a in get_roster():
        if a.get("providerKind") == "codex" and (not needle or needle in (a.get("id"), a.get("statusKey"), a.get("providerAgentId"), a.get("profile"))):
            return a
    return None


def _is_codex_agent(agent_id_or_key):
    needle = str(agent_id_or_key or "")
    for a in get_roster():
        if needle in (a.get("id"), a.get("statusKey"), a.get("providerAgentId"), a.get("profile")):
            return a.get("providerKind") == "codex"
    return needle.startswith("codex:") or needle.startswith("codex-")


def _codex_provider():
    codex_cfg = VO_CONFIG.get("codex", {})
    return CodexProvider(
        home_path=codex_cfg.get("homePath"),
        binary=codex_cfg.get("binary"),
        workspace_root=codex_cfg.get("workspaceRoot"),
        enabled=codex_cfg.get("enabled", True),
        timeout_sec=int(codex_cfg.get("timeoutSec") or 900),
        model=codex_cfg.get("model") or "",
        sandbox=codex_cfg.get("sandbox") or "workspace-write",
        approval_policy=codex_cfg.get("approvalPolicy") or "untrusted",
        prefer_app_server=codex_cfg.get("preferAppServer", True),
        main_workspace=codex_cfg.get("mainWorkspace"),
        include_main=codex_cfg.get("includeMain", True),
        include_native_agents=codex_cfg.get("includeNativeAgents", True),
        register_native_agents=codex_cfg.get("registerNativeAgents", True),
    )


# v0.13.1: the permission mode the owner chose for this agent in the chat window (agent_permissions.py), applied
# to the provider object of this one run. OpenClaw / Hermes keep their permissions in their own gateway.
_CODEX_APPROVAL_RANK = {"untrusted": 0, "on-failure": 1, "on-request": 1, "never": 2}


def _apply_codex_permissions(agent, provider):
    sandbox_ok = agent_permissions.codex_sandbox_works(getattr(provider, "binary", "") or "codex")
    mode, _saved = agent_permissions.current(STATUS_DIR, "codex", (agent or {}).get("id") or "",
                                             VO_CONFIG.get("codex", {}), sandbox_ok)
    provider.sandbox, provider.approval_policy = agent_permissions.codex_run_settings(mode, sandbox_ok)
    _apply_agent_run_settings("codex", agent, provider)
    return mode


def _apply_claude_code_permissions(agent, provider):
    mode, _saved = agent_permissions.current(STATUS_DIR, "claude-code", (agent or {}).get("id") or "",
                                             VO_CONFIG.get("claudeCode", {}))
    provider.permission_mode = agent_permissions.claude_permission_mode(mode)
    _apply_agent_run_settings("claude-code", agent, provider)
    return mode


def _apply_agent_run_settings(kind, agent, provider):
    """The model and thinking level picked for this agent in the chat window, for this run ("" = its own)."""
    saved = agent_permissions.run_settings(STATUS_DIR, kind, (agent or {}).get("id") or "")
    if saved["model"]:
        provider.model = saved["model"]
    provider.effort = saved["effort"]
    return saved


_AGENT_MODELS_CACHE = {}
_AGENT_MODELS_LOCK = threading.Lock()


def _agent_model_list(kind, provider, refresh=False):
    """The models (and thinking levels) the agent's program offers: Codex asks its app-server (kept 10 min)."""
    key = f"{kind}:{getattr(provider, 'binary', '') or ''}"
    now = time.time()
    with _AGENT_MODELS_LOCK:
        hit = _AGENT_MODELS_CACHE.get(key)
    if hit and not refresh and now - hit[0] < (600 if hit[1].get("ok") else 60):
        return hit[1]
    lister = getattr(provider, "list_models", None)
    try:
        result = lister() if callable(lister) else {"ok": False, "error": "This agent's program lists no models", "models": []}
    except Exception as exc:
        result = {"ok": False, "error": str(exc), "models": []}
    if not isinstance(result, dict):
        result = {"ok": False, "error": "Invalid model list", "models": []}
    with _AGENT_MODELS_LOCK:
        _AGENT_MODELS_CACHE[key] = (now, result)
    return result


def _agent_owner_only(access):
    """None for the office's owner; the refusal for anyone else (an agent, through the agent API token, never)."""
    agent_caller = bool(getattr(access, "via_token", False)) and not getattr(access, "via_session", False)
    if access is None or not getattr(access, "can_manage", False) or getattr(access, "as_agent", False) or agent_caller:
        return {"ok": False, "error": "Only the office's owner can change this.", "_status": 403}
    return None


def _agent_run_target(kind, agent_key):
    if kind == "codex":
        agent = _get_codex_agent(agent_key)
        return agent, (_codex_provider() if agent else None)
    if kind == "claude-code":
        agent = _get_claude_code_agent(agent_key)
        return agent, (_claude_code_provider() if agent else None)
    return None, None


def _agent_run_options_view(kind, agent_key, access, refresh=False):
    agent, provider = _agent_run_target(kind, agent_key)
    if not agent:
        return {"ok": False, "error": "This agent is not a Codex or Claude Code agent of this office.", "_status": 404}
    agent_id = agent.get("id") or agent_key
    listing = _agent_model_list(kind, provider, refresh)
    saved = agent_permissions.run_settings(STATUS_DIR, kind, agent_id)
    own = str(agent.get("model") or "").strip()
    own = "" if own == "inherit" else own
    own = own or str(getattr(provider, "model", "") or "")
    return {"ok": True, "kind": kind, "agent": agent_id, "model": saved["model"], "effort": saved["effort"],
            "agentModel": own, "models": listing.get("models") or [],
            "modelsError": "" if listing.get("ok") else str(listing.get("error") or ""),
            "canChange": _agent_owner_only(access) is None}


def _agent_run_options_set(body, access):
    body = body if isinstance(body, dict) else {}
    denied = _agent_owner_only(access)
    if denied:
        return denied
    kind = str(body.get("kind") or "").strip()
    agent_key = str(body.get("agent") or body.get("agentId") or "").strip()
    agent, provider = _agent_run_target(kind, agent_key)
    if not agent:
        return {"ok": False, "error": "This agent is not a Codex or Claude Code agent of this office.", "_status": 404}
    agent_id = agent.get("id") or agent_key
    changes = {k: str(body.get(k) or "").strip() for k in ("model", "effort") if k in body}
    if not changes:
        return {"ok": False, "error": "model or effort is required", "_status": 400}
    listing = _agent_model_list(kind, provider)
    models = {m.get("id"): m for m in (listing.get("models") or []) if isinstance(m, dict)}
    saved = agent_permissions.run_settings(STATUS_DIR, kind, agent_id)
    if changes.get("model") and models and changes["model"] not in models:
        return {"ok": False, "error": "That model is not offered here.", "_status": 400}
    # the model the next run uses: the one picked now, else the saved one, else the agent's own / the default
    model = changes["model"] if "model" in changes else saved["model"]
    default_model = next((mid for mid, m in models.items() if m.get("isDefault")), "")
    own = str(agent.get("model") or "").strip()
    meta = models.get(model or ("" if own == "inherit" else own) or default_model) or {}
    levels = {e.get("id") for e in (meta.get("effort") or []) if isinstance(e, dict)}
    if changes.get("effort") and models:
        offered = levels or {e.get("id") for m in models.values() for e in (m.get("effort") or []) if isinstance(e, dict)}
        if changes["effort"] not in offered:
            return {"ok": False, "error": "That thinking level is not offered for this model.", "_status": 400}
    if "model" in changes and "effort" not in changes and saved["effort"] and levels and saved["effort"] not in levels:
        changes["effort"] = ""   # (the new model does not have the saved level: back to the model's own)
    try:
        agent_permissions.set_run_settings(STATUS_DIR, kind, agent_id, **changes)
    except ValueError as exc:
        return {"ok": False, "error": str(exc), "_status": 400}
    except OSError as exc:
        print(f"🔐 Run settings: could not save {kind} agent {agent_id}: {exc}", flush=True)
        return {"ok": False, "error": "The office could not save this (agent-permissions.json in its data folder "
                "cannot be read or written). Nothing was changed.", "_status": 500}
    print(f"🧠 Run settings: {kind} agent {agent_id} -> " + ", ".join(f"{k}={v or 'default'}" for k, v in changes.items()), flush=True)
    return _agent_run_options_view(kind, agent_key, access)


def _apply_agent_permissions(kind, agent, provider):
    """Any Codex / Claude Code run, whoever starts it (the chat window, another agent, a meeting): the agent's mode."""
    if kind == "codex":
        return _apply_codex_permissions(agent, provider)
    if kind == "claude-code":
        return _apply_claude_code_permissions(agent, provider)
    return None


def _agent_permissions_target(kind, agent_key):
    if kind == "codex":
        agent = _get_codex_agent(agent_key)
        return agent, (_codex_provider() if agent else None)
    if kind == "claude-code":
        return _get_claude_code_agent(agent_key), None
    return None, None


def _agent_permissions_view(kind, agent_key, access):
    agent, provider = _agent_permissions_target(kind, agent_key)
    if not agent:
        return {"ok": False, "error": "This agent is not a Codex or Claude Code agent of this office.", "_status": 404}
    sandbox_ok = agent_permissions.codex_sandbox_works(getattr(provider, "binary", "") or "codex") if kind == "codex" else True
    cfg = VO_CONFIG.get("codex" if kind == "codex" else "claudeCode", {})
    can_change = access is not None and bool(getattr(access, "can_manage", False)) and not getattr(access, "as_agent", False)
    return agent_permissions.describe(STATUS_DIR, kind, agent.get("id") or agent_key, cfg, sandbox_ok, can_change)


def _agent_permissions_set(body, access):
    body = body if isinstance(body, dict) else {}
    kind = str(body.get("kind") or "").strip()
    agent_key = str(body.get("agent") or body.get("agentId") or "").strip()
    mode = str(body.get("mode") or "").strip()
    # Only the office's owner: an agent (the agent API token) never changes what agents may do
    if _agent_owner_only(access):
        return {"ok": False, "error": "Only the office's owner can change an agent's permissions.", "_status": 403}
    agent, provider = _agent_permissions_target(kind, agent_key)
    if not agent:
        return {"ok": False, "error": "This agent is not a Codex or Claude Code agent of this office.", "_status": 404}
    sandbox_ok = agent_permissions.codex_sandbox_works(getattr(provider, "binary", "") or "codex") if kind == "codex" else True
    try:
        agent_permissions.set_mode(STATUS_DIR, kind, agent.get("id") or agent_key, mode, sandbox_ok)
    except ValueError as exc:
        return {"ok": False, "error": str(exc), "_status": 400}
    except OSError as exc:
        print(f"🔐 Permissions: could not save {kind} agent {agent.get('id') or agent_key}: {exc}", flush=True)
        return {"ok": False, "error": "The office could not save this permission (agent-permissions.json in its data "
                "folder cannot be read or written). Nothing was changed.", "_status": 500}
    print(f"🔐 Permissions: {kind} agent {agent.get('id') or agent_key} -> {mode}", flush=True)
    return _agent_permissions_view(kind, agent_key, access)


def _codex_history_path(profile="default"):
    safe_profile = re.sub(r"[^a-zA-Z0-9_.-]+", "-", profile or "default")[:80] or "default"
    return os.path.join(STATUS_DIR, f"codex-chat-{safe_profile}.json")


def _load_codex_history(profile="default"):
    path = _codex_history_path(profile)
    try:
        with open(path, "r") as f:
            data = json.load(f)
        messages = data.get("messages", []) if isinstance(data, dict) else []
        return messages if isinstance(messages, list) else []
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return []


def _load_codex_session_history(profile="default", session_id=""):
    requested = str(session_id or "").strip()
    if not requested:
        return _load_codex_history(profile)
    state = _load_codex_state(profile)
    if str(state.get("sessionId") or "") == requested:
        return _chat_session_messages_with_id(state.get("messages"), requested)
    return _load_chat_session_mirror("codex", profile, requested)


def _load_codex_state(profile="default"):
    path = _codex_history_path(profile)
    with CODEX_STATE_LOCK:
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
            if isinstance(data, list):
                return {"messages": data, "sessionId": ""}
        except (FileNotFoundError, json.JSONDecodeError, OSError):
            pass
        return {"messages": [], "sessionId": ""}


def _save_codex_state(profile, state):
    path = _codex_history_path(profile)
    with CODEX_STATE_LOCK:
        data = dict(state) if isinstance(state, dict) else {}
        data["sessionId"] = str(data.get("sessionId") or "")
        data["messages"] = _chat_session_messages_with_id(data.get("messages"), data["sessionId"])
        if data["sessionId"]:
            data["messages"] = _save_chat_session_mirror("codex", profile, data["sessionId"], data["messages"])
        data["updatedAt"] = int(time.time() * 1000)
        _atomic_write_text(path, json.dumps(data, indent=2, ensure_ascii=False, default=str) + "\n")


def _codex_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _codex_context_used_from_token_usage(token_usage):
    token_usage = token_usage if isinstance(token_usage, dict) else {}
    last = token_usage.get("last") if isinstance(token_usage.get("last"), dict) else {}
    last_total = _codex_int(last.get("totalTokens"), 0)
    if last_total:
        return last_total
    last_input = _codex_int(last.get("inputTokens"), 0)
    if last_input:
        return last_input
    total = token_usage.get("total") if isinstance(token_usage.get("total"), dict) else {}
    return _codex_int(total.get("totalTokens"), 0)


def _codex_context_window_from_token_usage(token_usage):
    token_usage = token_usage if isinstance(token_usage, dict) else {}
    return _codex_int(token_usage.get("modelContextWindow"), 0)


def _get_codex_token_usage(profile="default"):
    state = _load_codex_state(profile)
    token_usage = state.get("tokenUsage") if isinstance(state.get("tokenUsage"), dict) else {}
    return token_usage


def _set_codex_token_usage(profile="default", token_usage=None):
    if not isinstance(token_usage, dict) or not token_usage:
        return
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        state["tokenUsage"] = token_usage
        state["contextUsed"] = _codex_context_used_from_token_usage(token_usage)
        context_window = _codex_context_window_from_token_usage(token_usage)
        if context_window:
            state["contextWindow"] = context_window
        _save_codex_state(profile, state)


def _clear_codex_token_usage(profile="default"):
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        for key in ("tokenUsage", "contextUsed", "contextWindow"):
            state.pop(key, None)
        _save_codex_state(profile, state)


def _save_codex_history(profile, messages):
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        state["messages"] = list(messages or [])[-500:]
        _save_codex_state(profile, state)


def _get_codex_session_id(profile="default"):
    state = _load_codex_state(profile)
    return str(state.get("sessionId") or "")


def _set_codex_session_id(profile="default", session_id=""):
    return _activate_codex_session(profile, session_id or "")


def _activate_codex_session(profile, session_id, messages=None):
    session_id = str(session_id or "")
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        if messages is None:
            messages = _load_chat_session_mirror("codex", profile, session_id)
            if not messages and str(state.get("sessionId") or "") == session_id:
                messages = state.get("messages") if isinstance(state.get("messages"), list) else []
        state["sessionId"] = session_id
        state["messages"] = _chat_session_messages_with_id(messages, session_id)
        _save_codex_state(profile, state)
        return state


def _update_codex_session_history(profile, session_id, updater):
    session_id = str(session_id or "")
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        if str(state.get("sessionId") or "") == session_id:
            current = state.get("messages") if isinstance(state.get("messages"), list) else []
        else:
            current = _load_chat_session_mirror("codex", profile, session_id)
        updated = updater(list(current))
        updated = updated if isinstance(updated, list) else current
        updated = _save_chat_session_mirror("codex", profile, session_id, updated) if session_id else updated[-500:]
        if str(state.get("sessionId") or "") == session_id:
            state["messages"] = updated
            _save_codex_state(profile, state)
        return updated


def _rekey_codex_session_history(profile, source_session_id, target_session_id):
    """Move a pending thread mirror to its native id without stealing focus."""
    source_session_id = str(source_session_id or "")
    target_session_id = str(target_session_id or "")
    if not source_session_id or not target_session_id or source_session_id == target_session_id:
        return _load_chat_session_mirror("codex", profile, target_session_id or source_session_id)
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        source_is_current = str(state.get("sessionId") or "") == source_session_id
        messages = state.get("messages") if source_is_current else _load_chat_session_mirror("codex", profile, source_session_id)
        messages = _save_chat_session_mirror("codex", profile, target_session_id, messages)
        _delete_chat_session_mirror("codex", profile, source_session_id)
        if source_is_current:
            state["sessionId"] = target_session_id
            state["messages"] = messages
            _save_codex_state(profile, state)
        return messages


def _set_codex_active_run(profile="default", session_id="", run_id=""):
    with CODEX_STATE_LOCK:
        state = _load_codex_state(profile)
        if session_id:
            state["sessionId"] = session_id
        state["runId"] = run_id or ""
        _save_codex_state(profile, state)


def _get_claude_code_agent(agent_id_or_key=None):
    needle = str(agent_id_or_key or "")
    for a in get_roster():
        if a.get("providerKind") == "claude-code" and (not needle or needle in (a.get("id"), a.get("statusKey"), a.get("providerAgentId"), a.get("profile"))):
            return a
    return None


def _is_claude_code_agent(agent_id_or_key):
    needle = str(agent_id_or_key or "")
    for a in get_roster():
        if needle in (a.get("id"), a.get("statusKey"), a.get("providerAgentId"), a.get("profile")):
            return a.get("providerKind") == "claude-code"
    return needle.startswith("claude-code:") or needle.startswith("claude-code-")


def _claude_code_provider():
    claude_cfg = VO_CONFIG.get("claudeCode", {})
    return ClaudeCodeProvider(
        home_path=claude_cfg.get("homePath"),
        binary=claude_cfg.get("binary"),
        workspace_root=claude_cfg.get("workspaceRoot"),
        enabled=claude_cfg.get("enabled", True),
        timeout_sec=int(claude_cfg.get("timeoutSec") or 900),
        model=claude_cfg.get("model") or "",
        permission_mode=claude_cfg.get("permissionMode") or "acceptEdits",
        main_workspace=claude_cfg.get("mainWorkspace"),
        include_main=claude_cfg.get("includeMain", True),
        include_native_agents=claude_cfg.get("includeNativeAgents", True),
        register_native_agents=claude_cfg.get("registerNativeAgents", True),
    )


def _claude_code_history_path(profile="main"):
    safe_profile = re.sub(r"[^a-zA-Z0-9_.-]+", "-", profile or "main")[:80] or "main"
    return os.path.join(STATUS_DIR, f"claude-code-chat-{safe_profile}.json")


def _load_claude_code_history(profile="main"):
    path = _claude_code_history_path(profile)
    try:
        with open(path, "r") as f:
            data = json.load(f)
        messages = data.get("messages", []) if isinstance(data, dict) else []
        return messages if isinstance(messages, list) else []
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return []


def _load_claude_code_session_history(profile="main", session_id=""):
    requested = str(session_id or "").strip()
    if not requested:
        return _load_claude_code_history(profile)
    state = _load_claude_code_state(profile)
    if str(state.get("sessionId") or "") == requested:
        return _chat_session_messages_with_id(state.get("messages"), requested)
    return _load_chat_session_mirror("claude-code", profile, requested)


def _load_claude_code_state(profile="main"):
    with CLAUDE_CODE_STATE_LOCK:
        path = _claude_code_history_path(profile)
        try:
            with open(path, "r") as f:
                data = json.load(f)
            state = data if isinstance(data, dict) else {"messages": []}
        except (FileNotFoundError, json.JSONDecodeError, OSError):
            state = {"messages": []}
        state["messages"] = state.get("messages") if isinstance(state.get("messages"), list) else []
        return state


def _save_claude_code_state(profile, state):
    with CLAUDE_CODE_STATE_LOCK:
        path = _claude_code_history_path(profile)
        data = dict(state) if isinstance(state, dict) else {}
        data["messages"] = data.get("messages") if isinstance(data.get("messages"), list) else []
        data["messages"] = _chat_session_messages_with_id(data["messages"], str(data.get("sessionId") or ""))
        data["updatedAt"] = int(time.time() * 1000)
        _atomic_write_text(path, json.dumps(data, indent=2))
        session_id = str(data.get("sessionId") or "")
        if session_id:
            _save_chat_session_mirror("claude-code", profile, session_id, data["messages"])


