# ---------------------------------------------------------------------------
# API Usage Collector — background thread that fetches quota data directly
# from provider APIs using credentials from OpenClaw auth profiles.
# No CLI dependency. Pure Python. Works in any environment.
# ---------------------------------------------------------------------------

# Provider display names
_PROVIDER_LABELS = {
    "anthropic": "Claude",
    "openai-codex": "Codex",
    "openai": "OpenAI",
    "github-copilot": "Copilot",
    "google-gemini-cli": "Gemini",
    "minimax": "MiniMax",
    "zai": "Z.AI",
}


class ApiUsageCollector:
    """Collects API usage/quota data directly from provider endpoints.

    Reads auth profiles from OpenClaw's auth-profiles.json, then calls each
    provider's usage API to get real quota windows (daily/weekly percentages,
    reset times, etc.).

    Runs in a background thread. The HTTP handler reads the cached result.
    """

    INTERVAL = 60  # seconds between collections
    REQUEST_TIMEOUT = 15  # seconds per provider API call

    def __init__(self, auth_profiles_path):
        self._auth_profiles_path = auth_profiles_path
        self._data = {"providers": [], "timestamp": 0, "source": "initializing"}
        self._lock = threading.Lock()
        self._thread = None

    def start(self):
        """Start the background collection thread."""
        self._thread = threading.Thread(target=self._run_loop, daemon=True, name="api-usage-collector")
        self._thread.start()

    def get_data(self):
        """Thread-safe read of the latest usage data."""
        with self._lock:
            return dict(self._data)

    def _run_loop(self):
        time.sleep(3)  # let server start
        while True:
            try:
                data = self._collect()
                with self._lock:
                    self._data = data
            except Exception as e:
                with self._lock:
                    self._data = {"providers": [], "timestamp": time.time(), "error": str(e), "source": "error"}
            time.sleep(self.INTERVAL)

    def _read_profiles(self):
        """Read OpenClaw auth profiles from the configured native store."""
        sqlite_profiles = self._read_profiles_from_sqlite()
        if sqlite_profiles:
            return sqlite_profiles
        try:
            with open(self._auth_profiles_path, "r") as f:
                ap = json.load(f)
            return ap.get("profiles", {})
        except Exception:
            return {}

    def _read_profiles_from_sqlite(self):
        db_path = os.path.join(OPENCLAW_AGENT_DIR, "openclaw-agent.sqlite")
        if not os.path.exists(db_path):
            return {}
        try:
            con = sqlite3.connect(db_path)
            con.row_factory = sqlite3.Row
            table_names = [
                row[0]
                for row in con.execute("select name from sqlite_master where type='table'")
            ]
            for table in ("auth_profile_store", "auth_profile_stores"):
                if table not in table_names:
                    continue
                cols = [row[1] for row in con.execute(f"pragma table_info({table})")]
                if "store_json" not in cols:
                    continue
                for row in con.execute(f"select store_json from {table}").fetchall():
                    try:
                        data = json.loads(row["store_json"] or "{}")
                    except Exception:
                        continue
                    profiles = data.get("profiles")
                    if isinstance(profiles, dict) and profiles:
                        con.close()
                        return profiles
            con.close()
        except Exception:
            return {}
        return {}

    def _profile_rank(self, profile):
        """Prefer profiles that can expose real quota windows over plain API keys."""
        prov = profile.get("provider", "")
        has_token = bool(profile.get("access") or profile.get("token"))
        has_key = bool(profile.get("key"))
        ptype = str(profile.get("type") or profile.get("mode") or "").lower()
        if prov in ("openai", "openai-codex") and has_token:
            return 0
        if prov == "anthropic" and has_token:
            return 0
        if prov == "github-copilot" and has_token:
            return 1
        if has_token or ptype in ("oauth", "token", "subscription"):
            return 2
        if has_key:
            return 5
        return 9

    def _collect(self):
        """Run one collection cycle across all configured providers."""
        now = time.time()
        profiles = self._read_profiles()
        if not profiles:
            return {"providers": [], "timestamp": now, "source": "no-profiles"}

        providers = []
        grouped = {}
        for pid, profile in profiles.items():
            if not isinstance(profile, dict):
                continue
            prov = profile.get("provider") or pid.split(":", 1)[0]
            if not prov:
                continue
            profile = dict(profile)
            profile["_profileId"] = pid
            canonical = "openai" if prov == "openai-codex" else prov
            grouped.setdefault(canonical, []).append(profile)

        for canonical, provider_profiles in grouped.items():
            provider_profiles.sort(key=self._profile_rank)
            profile = provider_profiles[0]
            prov = profile.get("provider") or canonical

            token = profile.get("access") or profile.get("token")
            api_key = profile.get("key")
            account_id = profile.get("accountId")

            result = None
            if prov == "anthropic" and token:
                result = self._fetch_claude(token, now)
            elif prov in ("openai", "openai-codex") and token:
                result = self._fetch_codex(token, account_id, now)
            elif prov == "github-copilot" and token:
                result = self._fetch_copilot(token, now)
            elif api_key and canonical not in ("ollama", "lmstudio"):
                result = {
                    "provider": canonical,
                    "displayName": _PROVIDER_LABELS.get(canonical, canonical.replace("-", " ").title()),
                    "type": "api_key",
                    "usage": None,
                    "status": "configured",
                    "message": "API key configured. This provider does not expose account quota windows through the standard API key interface.",
                }

            if result:
                result.setdefault("provider", canonical)
                result.setdefault("profileId", profile.get("_profileId", ""))
                result.setdefault("authType", str(profile.get("type") or profile.get("mode") or ("oauth" if token else "api_key")))
                result.setdefault("profilesFound", len(provider_profiles))
                providers.append(result)

        return {"providers": providers, "timestamp": now, "source": "openclaw-native-auth"}

    def _http_get(self, url, headers):
        """Make an HTTP GET request. Returns (status, response_body_dict_or_None)."""
        req = urllib.request.Request(url, headers=headers, method="GET")
        try:
            with urllib.request.urlopen(req, timeout=self.REQUEST_TIMEOUT) as resp:
                body = json.loads(resp.read().decode())
                return resp.status, body
        except urllib.error.HTTPError as e:
            # Try to parse error body
            try:
                body = json.loads(e.read().decode())
            except Exception:
                body = None
            return e.code, body
        except Exception:
            return 0, None

    # --- Anthropic (Claude) ---
    def _fetch_claude(self, token, now):
        """Fetch Claude usage from Anthropic OAuth endpoint."""
        status, data = self._http_get("https://api.anthropic.com/api/oauth/usage", {
            "Authorization": f"Bearer {token}",
            "User-Agent": "openclaw",
            "Accept": "application/json",
            "anthropic-version": "2023-06-01",
            "anthropic-beta": "oauth-2025-04-20",
        })
        entry = {
            "provider": "anthropic",
            "displayName": _PROVIDER_LABELS.get("anthropic", "Claude"),
            "type": "oauth",
        }
        if status != 200 or not data:
            msg = ""
            if data and isinstance(data, dict):
                msg = data.get("error", {}).get("message", "") if isinstance(data.get("error"), dict) else str(data.get("error", ""))
            entry["error"] = f"HTTP {status}: {msg}" if msg else f"HTTP {status}"
            if status == 429:
                entry["message"] = "Claude usage endpoint is rate limited. Model access can still work; usage will refresh after the provider allows another check."
            return entry

        # Parse usage windows
        windows = []
        if isinstance(data.get("five_hour"), dict) and data["five_hour"].get("utilization") is not None:
            windows.append({
                "label": "5h",
                "usedPercent": min(100, max(0, data["five_hour"]["utilization"])),
                "resetAt": int(self._parse_ts(data["five_hour"].get("resets_at"))) if data["five_hour"].get("resets_at") else 0,
            })
        if isinstance(data.get("seven_day"), dict) and data["seven_day"].get("utilization") is not None:
            windows.append({
                "label": "Week",
                "usedPercent": min(100, max(0, data["seven_day"]["utilization"])),
                "resetAt": int(self._parse_ts(data["seven_day"].get("resets_at"))) if data["seven_day"].get("resets_at") else 0,
            })
        # Model-specific windows (sonnet/opus)
        for key, label in [("seven_day_sonnet", "Sonnet"), ("seven_day_opus", "Opus")]:
            mw = data.get(key)
            if isinstance(mw, dict) and mw.get("utilization") is not None:
                windows.append({
                    "label": label,
                    "usedPercent": min(100, max(0, mw["utilization"])),
                })

        if windows:
            entry["usage"] = self._windows_to_usage(windows, now)
            entry["windows"] = windows
        return entry

    # --- OpenAI Codex ---
    def _fetch_codex(self, token, account_id, now):
        """Fetch ChatGPT/Codex usage from OpenAI's OAuth-backed usage endpoint."""
        headers = {
            "Authorization": f"Bearer {token}",
            "User-Agent": "CodexBar",
            "Accept": "application/json",
        }
        if account_id:
            headers["ChatGPT-Account-Id"] = account_id

        status, data = self._http_get("https://chatgpt.com/backend-api/wham/usage", headers)
        entry = {
            "provider": "openai",
            "displayName": _PROVIDER_LABELS.get("openai", "OpenAI"),
            "type": "oauth",
        }
        if status != 200 or not data:
            entry["error"] = f"HTTP {status}"
            entry["message"] = "OpenAI usage requires a valid ChatGPT/Codex OAuth session. API-key billing usage is not exposed here."
            return entry

        windows = []
        rl = data.get("rate_limit", {})

        # Primary window (usually 3h or 5h)
        pw = rl.get("primary_window")
        if pw:
            hours = round((pw.get("limit_window_seconds", 10800)) / 3600)
            windows.append({
                "label": f"{hours}h",
                "usedPercent": min(100, max(0, pw.get("used_percent", 0))),
                "resetAt": int(pw["reset_at"] * 1000) if pw.get("reset_at") else 0,
            })

        # Secondary window (usually week)
        sw = rl.get("secondary_window")
        if sw:
            hours = round((sw.get("limit_window_seconds", 86400)) / 3600)
            # Determine label
            label = "Week" if hours >= 168 else f"{hours}h" if hours < 24 else "Day"
            # Check if gap between resets suggests weekly
            if pw and sw.get("reset_at") and pw.get("reset_at"):
                if sw["reset_at"] - pw["reset_at"] >= 4320 * 60:
                    label = "Week"
            windows.append({
                "label": label,
                "usedPercent": min(100, max(0, sw.get("used_percent", 0))),
                "resetAt": int(sw["reset_at"] * 1000) if sw.get("reset_at") else 0,
            })

        # Plan info
        plan = data.get("plan_type")
        credits = data.get("credits", {})
        if credits.get("balance") is not None:
            balance = float(credits["balance"]) if credits["balance"] else 0
            plan = f"{plan} (${balance:.2f})" if plan else f"${balance:.2f}"
        entry["plan"] = plan

        if windows:
            entry["usage"] = self._windows_to_usage(windows, now)
            entry["windows"] = windows
        return entry

    # --- GitHub Copilot ---
    def _fetch_copilot(self, token, now):
        """Fetch GitHub Copilot usage."""
        status, data = self._http_get("https://api.github.com/copilot_internal/v2/token", {
            "Authorization": f"token {token}",
            "Accept": "application/json",
            "User-Agent": "openclaw",
        })
        entry = {
            "provider": "github-copilot",
            "displayName": _PROVIDER_LABELS.get("github-copilot", "Copilot"),
        }
        if status != 200:
            entry["error"] = f"HTTP {status}"
        # Copilot doesn't expose usage windows in the same way
        return entry

    # --- Helpers ---
    @staticmethod
    def _windows_to_usage(windows, now):
        """Convert raw windows list to structured usage object with pctLeft/timeLeft."""
        usage = {}
        for w in windows:
            label = (w.get("label") or "").lower()
            used = w.get("usedPercent", 0)
            left = 100 - used
            reset_at = w.get("resetAt", 0)
            time_left = ApiUsageCollector._format_time_left(reset_at, now) if reset_at else ""

            if label in ("5h", "day", "daily", "24h", "3h"):
                usage["dailyPctLeft"] = left
                usage["dailyWindow"] = w.get("label", "Day")
                usage["dailyTimeLeft"] = time_left
            elif label in ("week", "weekly"):
                usage["weeklyPctLeft"] = left
                usage["weeklyTimeLeft"] = time_left
            elif label in ("month", "monthly"):
                usage["monthlyPctLeft"] = left
                usage["monthlyTimeLeft"] = time_left
            elif label in ("sonnet", "opus"):
                usage[f"{label}PctLeft"] = left
            else:
                usage[f"{label}PctLeft"] = left
                usage[f"{label}TimeLeft"] = time_left
        return usage

    @staticmethod
    def _format_time_left(reset_at_ms, now_s):
        """Format time until reset as human-readable string."""
        diff = (reset_at_ms / 1000) - now_s
        if diff <= 0:
            return "resetting..."
        hours = int(diff // 3600)
        mins = int((diff % 3600) // 60)
        if hours > 24:
            days = hours // 24
            return f"{days}d {hours % 24}h"
        if hours > 0:
            return f"{hours}h {mins}m"
        return f"{mins}m"

    @staticmethod
    def _parse_ts(val):
        """Parse a timestamp string to milliseconds."""
        if not val:
            return 0
        if isinstance(val, (int, float)):
            return val * 1000 if val < 1e12 else val
        try:
            dt = datetime.fromisoformat(val.replace("Z", "+00:00"))
            return dt.timestamp() * 1000
        except Exception:
            return 0


# Initialize the collector (started in __main__)
_api_usage_collector = ApiUsageCollector(AUTH_PROFILES_PATH)


# ── Weather proxy ────────────────────────────────────────────────
# wttr.in j1 is ~40 KB, mostly hourly forecasts the office never reads. The
# office uses current_condition, nearest_area[0].latitude/longitude and
# weather[0].astronomy[0].sunrise/sunset (day/night), so pass exactly those.
_WEATHER_CACHE_TTL = 600
_WEATHER_CACHE = {"location": None, "at": 0.0, "body": None}
_WEATHER_CACHE_LOCK = threading.Lock()
_WEATHER_CURRENT_KEYS = (
    "FeelsLikeC", "FeelsLikeF", "cloudcover", "humidity", "observation_time", "precipInches", "precipMM",
    "pressure", "temp_C", "temp_F", "uvIndex", "visibility", "visibilityMiles", "weatherCode", "weatherDesc",
    "winddir16Point", "winddirDegree", "windspeedKmph", "windspeedMiles",
)
_WEATHER_AREA_KEYS = ("areaName", "country", "region", "latitude", "longitude")
_WEATHER_DAY_KEYS = ("date", "maxtempC", "maxtempF", "mintempC", "mintempF", "avgtempC", "avgtempF", "sunHour", "uvIndex")
_WEATHER_ASTRO_KEYS = ("sunrise", "sunset", "moonrise", "moonset", "moon_phase", "moon_illumination")


def _shape_weather_payload(raw):
    """Trim a wttr.in j1 payload to what the office reads. Raises ValueError when
    the upstream answer is not a j1 object (wttr.in answers some errors as text)."""
    data = json.loads(raw.decode("utf-8") if isinstance(raw, (bytes, bytearray)) else raw)
    if not isinstance(data, dict) or not isinstance(data.get("current_condition"), list):
        raise ValueError("weather service returned an unexpected answer")

    def pick(obj, keys):
        return {k: obj[k] for k in keys if isinstance(obj, dict) and k in obj}

    out = {"configured": True, "current_condition": [pick(c, _WEATHER_CURRENT_KEYS) for c in data["current_condition"][:1]]}
    areas = data.get("nearest_area") if isinstance(data.get("nearest_area"), list) else []
    out["nearest_area"] = [pick(a, _WEATHER_AREA_KEYS) for a in areas[:1]]
    days = data.get("weather") if isinstance(data.get("weather"), list) else []
    shaped_days = []
    for day in days[:3]:
        if not isinstance(day, dict):
            continue
        item = pick(day, _WEATHER_DAY_KEYS)
        astro = day.get("astronomy") if isinstance(day.get("astronomy"), list) else []
        item["astronomy"] = [pick(a, _WEATHER_ASTRO_KEYS) for a in astro[:1]]
        shaped_days.append(item)
    out["weather"] = shaped_days
    return out


def _fetch_weather_payload(location, now=None):
    """Shaped weather for `location`, cached for 10 minutes across all clients."""
    now = time.time() if now is None else now
    with _WEATHER_CACHE_LOCK:
        if _WEATHER_CACHE["location"] == location and _WEATHER_CACHE["body"] is not None and now - _WEATHER_CACHE["at"] < _WEATHER_CACHE_TTL:
            return _WEATHER_CACHE["body"]
    encoded = urllib.parse.quote(location, safe='')
    req = urllib.request.Request(f"https://wttr.in/{encoded}?format=j1", headers={"User-Agent": "curl/7.68"})
    with urllib.request.urlopen(req, timeout=10) as resp:
        raw = resp.read(2 * 1024 * 1024)
    body = _shape_weather_payload(raw)
    with _WEATHER_CACHE_LOCK:
        _WEATHER_CACHE.update(location=location, at=now, body=body)
    return body


class VirtualOfficeThreadingHTTPServer(http.server.ThreadingHTTPServer):
    """Threading server that keeps routine client disconnects out of logs."""

    # Page load plus pollers from several tabs arrive in bursts; the default
    # backlog of 5 caused 1 s SYN-retry stalls (BE-25).
    request_queue_size = 128

    def handle_error(self, request, client_address):
        error = sys.exc_info()[1]
        if isinstance(error, (BrokenPipeError, ConnectionResetError, ConnectionAbortedError)):
            return
        if isinstance(error, OSError) and getattr(error, "errno", None) in {32, 54, 103, 104}:
            return
        super().handle_error(request, client_address)


class _BufferedResponseWriter:
    """File-like stand-in for ``handler.wfile`` that holds the response until the
    route finishes, so a crash can still become a JSON 500 and finished bodies can
    be compressed and tagged. ``flush()`` (used by event streams) or a body over
    the buffer limit switches to pass-through streaming."""

    def __init__(self, handler, raw):
        self._handler = handler
        self._raw = raw

    def write(self, data):
        handler = self._handler
        if handler._vo_committed:
            return self._raw.write(data)
        chunk = bytes(data)
        handler._vo_body.append(chunk)
        handler._vo_body_size += len(chunk)
        if handler._vo_body_size > _RESPONSE_BUFFER_LIMIT:
            handler._vo_commit(final=False)
        return len(chunk)

    def writelines(self, lines):
        for line in lines:
            self.write(line)

    def flush(self):
        handler = self._handler
        if not handler._vo_committed and handler._vo_headers_done:
            handler._vo_commit(final=False)
        if handler._vo_committed:
            self._raw.flush()

    def writable(self):
        return True

    @property
    def closed(self):
        return getattr(self._raw, "closed", False)


class _RequestError(Exception):
    """Raised by request helpers; becomes a JSON error response (BE-23)."""

    def __init__(self, status, error, message="", fix=None):
        super().__init__(message or error)
        self.status = status
        self.error = error
        self.message = message or error
        self.fix = fix


_JSON_BODY_MAX_BYTES = _env_int("VO_JSON_BODY_MAX_BYTES", 16 * 1024 * 1024, minimum=64 * 1024, maximum=256 * 1024 * 1024)
_RESPONSE_BUFFER_LIMIT = 6 * 1024 * 1024
_GZIP_MIN_BYTES = 1024
_GZIP_CONTENT_TYPES = (
    "text/", "application/json", "application/javascript", "application/x-javascript",
    "image/svg+xml", "application/manifest+json", "application/xml",
)
_GZIP_CACHE = OrderedDict()
_GZIP_CACHE_BYTES = 0
_GZIP_CACHE_MAX_BYTES = 24 * 1024 * 1024
_GZIP_CACHE_LOCK = threading.Lock()


def _gzip_cached(body):
    """gzip ``body``; large repeated bodies (static files) are compressed once."""
    global _GZIP_CACHE_BYTES
    key = hashlib.sha1(body).digest()
    with _GZIP_CACHE_LOCK:
        hit = _GZIP_CACHE.get(key)
        if hit is not None:
            _GZIP_CACHE.move_to_end(key)
            return hit
    packed = gzip.compress(body, compresslevel=6, mtime=0)
    if len(body) >= 32 * 1024:
        with _GZIP_CACHE_LOCK:
            if key not in _GZIP_CACHE:
                _GZIP_CACHE[key] = packed
                _GZIP_CACHE_BYTES += len(packed)
            while _GZIP_CACHE_BYTES > _GZIP_CACHE_MAX_BYTES and _GZIP_CACHE:
                _old_key, old = _GZIP_CACHE.popitem(last=False)
                _GZIP_CACHE_BYTES -= len(old)
    return packed


# Routes polled by every open tab: successful hits are not access-logged (BE-26).
_QUIET_LOG_PATHS = {
    "/status", "/agents-list", "/agent-chat", "/vo-config", "/browser-status", "/browser-screenshot",
    "/api/previews", "/session-info", "/api/office/presence", "/pc-metrics", "/gateway-info",
    "/api/meetings/active", "/api/access/status", "/health", "/api/codex/approval/pending",
    "/api/hermes/approval/pending", "/api/hermes/approval/stream", "/sms-unread", "/api/api-usage",
    "/weather", "/api/office/chat-sessions", "/api/hermes/history", "/api/codex/history",
    "/api/claude-code/history", "/api/openclaw/rpc", "/api/session-progress", "/api-usage",
}
_QUIET_LOG_PREFIXES = (
    "/api/projects", "/api/hermes/runs/", "/api/codex/runs/", "/api/claude-code/runs/",
    "/api/provider-runs/", "/api/openclaw/events", "/api/agent-pc/", "/api/previews/",
    "/api/office-life/state", "/api/office-life/stream", "/api/office-life/journal",
)
_STATIC_EXTENSIONS = {
    ".html", ".js", ".mjs", ".css", ".png", ".jpg", ".jpeg", ".gif", ".svg", ".webp", ".ico",
    ".woff", ".woff2", ".ttf", ".otf", ".mp3", ".wav", ".ogg", ".webm", ".mp4", ".txt",
}
_STATIC_ALLOWED_JSON = {"manifest.json"}
_STATIC_DENIED_PARTS = {"tests", "providers", "__pycache__", "backups", "node_modules", "provider-layer"}
_ASSET_TOKEN_CACHE = {}
_ASSET_TOKEN_LOCK = threading.Lock()
_ASSET_REF_RE = re.compile(r"""((?:src|href)\s*=\s*["'])([^"'?#]+)\?v=[^"'#]*""")


def _static_file_for_path(url_path):
    """Map a URL path to a servable file under APP_DIR, or None (allowlist, BE-28/DL-06)."""
    rel = urllib.parse.unquote(str(url_path or "/")).split("?", 1)[0].split("#", 1)[0]
    if rel in {"", "/"}:
        rel = "/index.html"
    if "\\" in rel or "\x00" in rel:
        return None
    parts = [part for part in rel.split("/") if part not in {"", "."}]
    if not parts or any(part == ".." or part.startswith(".") for part in parts):
        return None
    if any(part in _STATIC_DENIED_PARTS for part in parts[:-1]):
        return None
    name = parts[-1]
    ext = os.path.splitext(name)[1].lower()
    if ext not in _STATIC_EXTENSIONS and not (len(parts) == 1 and name in _STATIC_ALLOWED_JSON):
        return None
    root = os.path.realpath(APP_DIR)
    full = os.path.realpath(os.path.join(root, *parts))
    if not full.startswith(root + os.sep) or not os.path.isfile(full):
        return None
    return full


def _asset_token(full_path, _seen=None):
    """Short cache-busting token for a file, derived from its mtime and size (C7). A module or style
    sheet with ``?v=`` references of its own (I7) also covers its targets' tokens: a changed target
    gives every file that names it a new URL too, so an immutable copy is never stale."""
    try:
        st = os.stat(full_path)
    except OSError:
        return ""
    deps = ""
    if full_path.endswith(_NESTED_REF_EXTENSIONS):
        seen = (_seen or frozenset()) | {full_path}
        deps = ",".join(_asset_token(target, seen) for target in _nested_ref_targets(full_path) if target not in seen)
    key = (st.st_mtime_ns, st.st_size, deps)
    with _ASSET_TOKEN_LOCK:
        cached = _ASSET_TOKEN_CACHE.get(full_path)
        if cached and cached[0] == key:
            return cached[1]
        seed = f"{full_path}:{st.st_mtime_ns}:{st.st_size}" + (f":{deps}" if deps else "")
        token = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:12]
        _ASSET_TOKEN_CACHE[full_path] = (key, token)
        return token


# ``?v=`` references inside served modules and style sheets (I7): ``from './x.mjs?v=..'``,
# ``import('./x.mjs?v=..')``, ``url("x.woff2?v=..")``. Served rewritten to their targets' tokens.
_NESTED_REF_RE = re.compile(r"""((?:\bfrom|\bimport\s*\(|\burl\()\s*["'])([^"'?#\s()]+)\?v=[^"'#\s()]*""")
_NESTED_REF_EXTENSIONS = (".mjs", ".css")
_NESTED_REF_CACHE = {}


def _resolve_asset_ref(ref, base_dir):
    """The real path of a local reference under APP_DIR, or ''."""
    if "://" in ref or ref.startswith("//") or ref.startswith("data:"):
        return ""
    root = os.path.realpath(APP_DIR)
    target = os.path.realpath(os.path.join(root, ref.lstrip("/")) if ref.startswith("/") else os.path.join(base_dir, ref))
    return target if target.startswith(root + os.sep) and os.path.isfile(target) else ""


def _nested_ref_targets(full_path):
    """Files a .mjs/.css names with ``?v=`` (cached by mtime and size)."""
    try:
        st = os.stat(full_path)
        key = (st.st_mtime_ns, st.st_size)
        cached = _NESTED_REF_CACHE.get(full_path)
        if cached and cached[0] == key:
            return cached[1]
        with open(full_path, "r", encoding="utf-8", errors="replace") as handle:
            text = handle.read()
    except OSError:
        return ()
    base = os.path.dirname(full_path)
    targets = tuple(t for t in (_resolve_asset_ref(m.group(2), base) for m in _NESTED_REF_RE.finditer(text)) if t)
    _NESTED_REF_CACHE[full_path] = (key, targets)
    return targets


def _rewrite_asset_tokens(html_text, base_dir=None, pattern=None):
    """Replace every ``?v=...`` on a local src/href (or ``pattern``) with the target file's token."""
    root = os.path.realpath(APP_DIR)
    base_dir = base_dir or root

    def _sub(match):
        prefix, ref = match.group(1), match.group(2)
        if "://" in ref or ref.startswith("//") or ref.startswith("data:"):
            return match.group(0)
        target = os.path.realpath(os.path.join(root, ref.lstrip("/")) if ref.startswith("/") else os.path.join(base_dir, ref))
        token = _asset_token(target) if target.startswith(root + os.sep) else ""
        return f"{prefix}{ref}?v={token}" if token else match.group(0)

    return (pattern or _ASSET_REF_RE).sub(_sub, html_text)


